window.COURSE = {"title": "Хмарні технології та сервіси", "lectures": [{"id": "w1l1", "num": 1, "week": 1, "title": "Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "url": "lectures/week-1/lecture-1.html", "minutes": 13}, {"id": "w1l2", "num": 2, "week": 1, "title": "Linux: основи ОС, команди, користувачі та права доступу", "url": "lectures/week-1/lecture-2.html", "minutes": 14}, {"id": "w1l3", "num": 3, "week": 1, "title": "Bash: скрипти, змінні, умови, цикли та функції", "url": "lectures/week-1/lecture-3.html", "minutes": 17}, {"id": "w1l4", "num": 4, "week": 1, "title": "Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "url": "lectures/week-1/lecture-4.html", "minutes": 14}, {"id": "w1l5", "num": 5, "week": 1, "title": "LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "url": "lectures/week-1/lecture-5.html", "minutes": 12}, {"id": "w2l6", "num": 6, "week": 2, "title": "Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "url": "lectures/week-2/lecture-6.html", "minutes": 15}, {"id": "w2l7", "num": 7, "week": 2, "title": "Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "url": "lectures/week-2/lecture-7.html", "minutes": 10}, {"id": "w2l8", "num": 8, "week": 2, "title": "Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "url": "lectures/week-2/lecture-8.html", "minutes": 13}, {"id": "w2l9", "num": 9, "week": 2, "title": "Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "url": "lectures/week-2/lecture-9.html", "minutes": 12}, {"id": "w2l10", "num": 10, "week": 2, "title": "Системи контролю версій: Git, гілки, Git Flow і pull request", "url": "lectures/week-2/lecture-10.html", "minutes": 12}, {"id": "w3l11", "num": 11, "week": 3, "title": "CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "url": "lectures/week-3/lecture-11.html", "minutes": 13}, {"id": "w3l12", "num": 12, "week": 3, "title": "GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "url": "lectures/week-3/lecture-12.html", "minutes": 13}], "search": [{"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Вступ", "url": "lectures/week-1/lecture-1.html", "text": ""}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-1.html#goals", "text": "Чого ви навчитесь Пояснити, що таке DevOps і чому це культура + практики + інструменти , а не посада «адміна з Docker». Назвати 4 принципи CAMS і ключові DevOps-практики (CI, CD, IaC, моніторинг, контейнери). Розрізняти IaaS, PaaS, SaaS і On-Premises за тим, хто чим керує. Порівняти Waterfall , ітеративні моделі та Agile (Scrum, Kanban, XP). Відрізнити бібліотеку від фреймворку і пояснити, що таке CRUD-застосунок."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Програмне забезпечення і CRUD", "url": "lectures/week-1/lecture-1.html#software", "text": "Програмне забезпечення і CRUD Програмне забезпечення (software) — це набір програм і пов'язаних даних , які кажуть комп'ютеру, що і як робити, разом із документацією. Без ПЗ комп'ютер — «просто меблі». Чому наголос на даних ? Майже кожен вебресурс (інтернет-магазин, соцмережа) зберігає дані в базі. Якщо впаде база — сайт формально працює, але стає марним. Тому DevOps-інженер відповідає не лише за код, а й за збереження та резервне копіювання даних. Визначення CRUD — Create, Read, Update, Delete. З будь-якою інформаційною сутністю (товар, користувач, пост) можна зробити лише ці 4 дії, тому більшість застосунків — це «CRUD-застосунки». Пізніше (лекція 4) побачимо, що CRUD напряму відображається на HTTP-методи POST/GET/PUT/DELETE."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Що таке DevOps", "url": "lectures/week-1/lecture-1.html#devops", "text": "Що таке DevOps Визначення (AWS) DevOps — поєднання культурних філософій, практик та інструментів, яке підвищує здатність організації постачати застосунки та сервіси з високою швидкістю . Проблема: «стіна непорозуміння» Класично розробники (Dev) хочуть часто випускати зміни, а експлуатація (Ops) — щоб система була стабільною. Кожна група має власні інструменти й цілі. Розробники «перекидають через стіну» новий реліз, адміністратори його розгортають — і щось ламається. Agile свого часу зблизив бізнес і розробку; DevOps зближує розробку й експлуатацію . Навіщо DevOps. Agile зближує бізнес і розробку, DevOps — розробку й експлуатацію. Що потрібно від DevOps Робимо Замість Автоматизуємо процеси ручного виконання Автоматичний журнал змін (audit trail) бюрократії Співпрацюємо «перекидання через стіну» Спільна автоматизація повторення одного й того ж кожною командою Принципи CAMS Culture Культура Agile-підхід і спільна відповідальність за весь конвеєр постачання. Automation Автоматизація Вища швидкість і частота релізів, менше ручної праці. Measurement Вимірювання Збираємо метрики: усе в інфраструктурі виміряно і візуалізовано. Sharing Обмін Спільні цілі, знання та інструменти у Dev і Ops. DevOps-цикл і практики DevOps-цикл. Ліва петля — розробка, права — експлуатація; моніторинг повертає зворотний зв'язок у планування. Ключові DevOps-практики зі слайдів: Continuous Integration , Continuous Delivery , Infrastructure as Code (IaC) , моніторинг і логування, мікросервіси, віртуалізація та контейнеризація, безперервний моніторинг. Типові інструменти: Jenkins, TeamCity, Maven/Gradle, Docker, Vagrant, Terraform, Ansible/Chef/Puppet, SonarQube, Nagios/Zabbix, хмари AWS/Azure/GCP. Кожну практику ми розберемо в окремій лекції."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "CI, Continuous Delivery і Continuous Deployment", "url": "lectures/week-1/lecture-1.html#cicd", "text": "CI, Continuous Delivery і Continuous Deployment CI → CD. Різниця між Delivery і Deployment — лише в останньому кроці: людина чи автомат вирішує випуск у production. Continuous Integration (CI) — розробники часто зливають код у спільний репозиторій; CI-сервер (наприклад, Jenkins) на кожну зміну збирає проєкт і проганяє тести, повертаючи швидкий зворотний зв'язок. Continuous Delivery — кожна успішна збірка автоматично доходить до staging і готова до релізу; у production — після ручного схвалення. Continuous Deployment — у production теж автоматично, без людини."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Хмари і моделі сервісів [X]aaS", "url": "lectures/week-1/lecture-1.html#cloud", "text": "Хмари і моделі сервісів [X]aaS Визначення NIST Хмарні обчислення — модель повсюдного, зручного мережевого доступу на вимогу до спільного пулу конфігурованих ресурсів (мережі, ВМ, сховища, застосунки, сервіси), які можна швидко виділити й звільнити з мінімальними зусиллями з управління. Економічний сенс: замість CapEx (капітальні витрати — купити сервери наперед) компанія платить OpEx (операційні витрати — оренда за фактом використання). Хто чим керує. Що вище модель — то менше контролю і менше турбот. Модель Що отримуєте Хто користувач Приклади IaaS — Infrastructure ВМ, мережа, диски. ОС і все вище — ваше адміністратори, DevOps AWS EC2, Azure VM, Google Compute Engine PaaS — Platform готове середовище запуску коду розробники Heroku, AWS Elastic Beanstalk, Google App Engine SaaS — Software готовий застосунок у браузері кінцеві користувачі Gmail, Google Docs, Office 365, Trello, Salesforce Мнемоніка зі слайдів: SaaS — Use it , PaaS — Build with it , IaaS — Move to it . Популярна аналогія — «піца як сервіс»: вдома робите все самі (On-Premises), купуєте напівфабрикат і печете (IaaS), замовляєте доставку (PaaS), йдете в піцерію (SaaS). Межа між PaaS і SaaS на практиці тонка. Як почати безкоштовно Великі провайдери дають free tier: AWS Free Tier, Google Cloud Free Tier, Microsoft Azure Free Account. Детальніше про хмари — у лекції 7."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Бібліотека vs фреймворк", "url": "lectures/week-1/lecture-1.html#framework", "text": "Бібліотека vs фреймворк Фреймворк — готовий каркас програмних рішень (архітектура + базова функціональність). Перевага: усі системи на ньому мають однакову структуру. Бібліотека (library) Набір функцій для повторного використання. Ви викликаєте бібліотеку, керування повертається вам. Легко додати в наявний проєкт через API. Приклад: Chart.js — для графіків. Фреймворк (framework) Диктує архітектуру проєкту. Фреймворк викликає ваш код (інверсія керування). Зазвичай обирається на старті нового проєкту. Приклад: Angular — для вебзастосунків."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "SDLC і моделі розробки", "url": "lectures/week-1/lecture-1.html#sdlc", "text": "SDLC і моделі розробки SDLC (Software Development Life Cycle) — поділ роботи над ПЗ на фази для кращого планування: аналіз → проєктування → реалізація → тестування (+ розгортання і супровід). Будь-яка програма, мала чи велика, проходить ці кроки. Модель Ідея Коли доречна Waterfall (водоспад) Послідовні фази згори вниз: бізнес-вимоги → вимоги користувача → системні вимоги → архітектура → детальний дизайн → реалізація → тестування. Повернутися назад дорого. Вимоги стабільні й відомі наперед Ітеративна Кожна ітерація — закритий «міні-проєкт» (вимоги, дизайн, код, інтеграція, тести). Наприкінці — повністю протестована версія і відгук стейкхолдерів у план наступної ітерації. Вимоги уточнюються в процесі Еволюційне прототипування Прототип поступово доводиться до готового продукту. Нечіткі вимоги, потрібен ранній фідбек Agile Мінімізує ризик, контролюючи 4 змінні: ресурси, час, якість і особливо обсяг (scope) . Більшість сучасних продуктів Цінності Agile-маніфесту Люди і взаємодія важливіші за процеси та інструменти. Працюючий продукт важливіший за вичерпну документацію. Співпраця із замовником важливіша за узгодження контракту. Готовність до змін важливіша за дотримання плану. Популярні Agile-методології: Scrum (фіксовані спринти, ролі, церемонії), Kanban (безперервний потік задач на дошці з лімітом незавершеної роботи), XP — eXtreme Programming (інженерні практики: парне програмування, TDD, часті релізи)."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Від хостингу 199x до DevOps-інженера", "url": "lectures/week-1/lecture-1.html#history", "text": "Від хостингу 199x до DevOps-інженера 199x — власне залізо. Компанія купує сервери, мережу, приміщення, наймає адмінів і платить за все, навіть якщо ресурс простоює. 2000-ні — спільні дата-центри. Оренда стійок, але сервери й ПЗ досі свої. Ера сервісів. Хмари, IaaS/PaaS/SaaS, автоматизація. Типова сучасна інфраструктура: балансувальник (NGINX/HAProxy) → кілька вебсерверів (httpd/Tomcat) → основна та резервна БД MySQL. Без моніторингу важко навіть зрозуміти, що «щось не так». DevOps-інженер потрібен практично на кожному середньому/великому проєкті: Linux, мережі, скрипти, хмари, IaC, контейнери, Git, CI/CD — саме ці теми й складають цей курс."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Типові помилки", "url": "lectures/week-1/lecture-1.html#mistakes", "text": "Типові помилки DevOps — це посада або конкретний інструмент (Docker, Jenkins). DevOps — це культура + практики + інструменти. Інструменти лише реалізують принципи CAMS. Continuous Delivery і Continuous Deployment — синоніми. У Delivery реліз у production схвалює людина; у Deployment він автоматичний. У PaaS я налаштовую ОС і встановлюю runtime. ОС, middleware і runtime в PaaS — зона провайдера. Ваші — лише застосунок і дані. Керування ОС — це IaaS. Фреймворк — це просто «велика бібліотека». Ключова різниця — хто кого викликає: бібліотеку викликаєте ви, фреймворк викликає ваш код."}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Вступ", "url": "lectures/week-1/lecture-2.html", "text": ""}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-2.html#goals", "text": "Чого ви навчитесь Пояснити, чим Linux відрізняється від Windows і де шукати файли в дереві каталогів. Впевнено користуватися базовими командами: навігація, файли, процеси, мережа, пакети. Комбінувати команди через pipe | та перенаправлення > , >> . Керувати користувачами і групами ( useradd , usermod , sudo ). Читати й змінювати права: rwx , числа 755 , chmod / chown , SUID/SGID/sticky bit. Налаштувати вхід на сервер за SSH-ключем."}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Чому саме Linux", "url": "lectures/week-1/lecture-2.html#why", "text": "Чому саме Linux Операційна система (ОС) керує залізом і дає програмам спільні сервіси: процеси, пам'ять, файли, мережу, користувачів. Linux належить до сімейства Unix-подібних (*nix) систем. Ядро анонсував Лінус Торвальдс у 1991 році; з 1992 воно поширюється за ліцензією GNU GPL — тоді ж з'явилися перші дистрибутиви. Безкоштовна і з відкритим кодом. Немає ліцензій на кожен сервер. Домінує на серверах — за даними зі слайдів, близько 70% інтернет-серверів працюють на *nix. Android теж побудований на ядрі Linux. Можна працювати взагалі без графічного інтерфейсу — тільки термінал, що ідеально для серверів. Linux vs Windows: ключові відмінності Linux Windows Одне дерево від кореня / , немає дисків C: , D: Окремі диски з літерами Розділювач шляху / \\ Регістр має значення : File.txt ≠ file.txt Регістр не враховується Суперкористувач — root Administrator Виконуваність файла визначає атрибут x Розширення .exe , .bat , .cmd Десятки графічних оболонок або без GUI взагалі Одна вбудована GUI Дистрибутиви поділяються на сімейства, від яких залежить пакетний менеджер: Debian (Debian, Ubuntu, Mint) — dpkg , apt ; Red Hat (RHEL, CentOS, Fedora) — rpm , yum ."}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Структура каталогів", "url": "lectures/week-1/lecture-2.html#fs", "text": "Структура каталогів У Linux «майже все — файл»: звичайні файли, каталоги, пристрої, навіть більшість команд — це програми-файли в /bin . Одне дерево від кореня. Конфіги шукайте в /etc , логи — у /var/log , сайти Apache — у /var/www/html ."}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Команди, які треба знати", "url": "lectures/week-1/lecture-2.html#commands", "text": "Команди, які треба знати Більшість команд мають ключі (опції), що змінюють поведінку. Довідка: man <команда> . Задача Команда Перейти в каталог / на рівень вгору / в корінь / додому cd dir , cd .. , cd / , cd ~ Список файлів (з прихованими і деталями) ls -al Створити порожній файл / каталог touch f , mkdir d Копіювати (рекурсивно — каталог) cp src dst , cp -r dir newdir Перемістити / перейменувати mv old new , mv *.c newproj Видалити файл (з підтвердженням) / порожній каталог rm f , rm -i f , rmdir d Переглянути вміст cat f , more f Символічне / жорстке посилання ln -s orig link , ln orig link Виконати від root / змінити користувача sudo cmd , su user Вимкнути / перезавантажити (root) shutdown -h now , shutdown -r now Ядро і архітектура / CPU uname -a , lscpu Процеси (знімок / у реальному часі) ps aux , top Мережеві інтерфейси / поточний користувач ip addr show , id Символічне посилання — «ярлик», що вказує на ім'я файла (зламається, якщо оригінал видалити). Жорстке — ще одне ім'я для тих самих даних на диску (дані живуть, поки є хоч одне ім'я). Встановлення і запуск програм Програми встановлюються з репозиторіїв (аналог Google Play): офіційних для дистрибутиву або сторонніх. Встановлювати може лише root (або через sudo ). Файл запускається, якщо має атрибут x — розширення не важливе. Скрипт у поточному каталозі запускають так: ./program.sh . sudo apt install git # Debian/Ubuntu sudo yum install git # RHEL/CentOS chmod +x program.sh && ./program.sh"}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Pipes і перенаправлення вводу-виводу", "url": "lectures/week-1/lecture-2.html#pipes", "text": "Pipes і перенаправлення вводу-виводу Два механізми. Pipe з'єднує програми, перенаправлення змінює куди йде результат. ps aux | grep apache # усі процеси apache ls -a | grep myfile # файли, в імені яких є myfile uname -a > mysystem.info # зберегти інфо про систему у файл date >> log.txt # дописати рядок у кінець log.txt"}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Користувачі та групи", "url": "lectures/week-1/lecture-2.html#users", "text": "Користувачі та групи Linux — повністю багатокористувацька ОС. Кожен користувач і група мають ім'я та числовий ідентифікатор (UID/GID). Користувач має одну основну (primary) групу і може мати кілька додаткових (secondary) . /etc/passwd — облікові записи; /etc/shadow — хеші паролів (читає лише root); /etc/group — групи. groupadd developers # створити групу grep developers /etc/group # перевірити, що група існує useradd -G developers vivek # користувач з додатковою групою passwd vivek # задати пароль id vivek # UID, GID і всі групи useradd -g developers tony # -g = основна група usermod -a -G ftp tony # -a -G = ДОДАТИ ще одну групу usermod -g www tony # змінити основну групу chage -d 0 tony # змусити змінити пароль при вході usermod -L tony # заблокувати пароль usermod -aG wheel tony # CentOS: група wheel = права sudo Пастка usermod -G ftp tony без -a замінить усі додаткові групи користувача однією ftp . Для додавання завжди пишіть -aG ."}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Права доступу до файлів", "url": "lectures/week-1/lecture-2.html#perms", "text": "Права доступу до файлів Кожен файл має власника (u — user) , групу (g) і всіх інших (o — others) . Для кожної категорії — три права: r (read, 4), w (write, 2), x (execute, 1). Число для категорії — сума прав. Як читати права. Три трійки rwx → три цифри. -rwxr-xr-- = 754 . chmod: абсолютна і відносна форма chmod 755 deploy.sh # абсолютно: rwxr-xr-x (попередні права не враховуються) chmod 644 index.html # rw-r--r-- — типово для вебфайлів chmod u+x script.sh # відносно: додати власнику виконання chmod go-w file # забрати запис у групи та інших chmod a+r file # a = all (усім) — додати читання chmod -R 775 opencart # рекурсивно для каталогу chown / chgrp: власник і група chown tony file1 file2 # змінити власника chgrp sales /home/sales/* # змінити групу chown -R tony:www site/ # власник і група рекурсивно chown -R apache:apache opencart # типово: віддати сайт вебсерверу Спеціальні біти SUID — chmod u+s Запуск від імені власника Напр. /usr/bin/passwd має s : звичайний користувач змінює пароль, а програма пише в /etc/shadow з правами root. SGID на каталозі — chmod g+s Спільна група Нові файли в каталозі успадковують групу каталогу — зручно для спільної папки команди. Sticky bit — chmod +t Видаляє лише власник У каталог можуть писати всі, але видалити файл може тільки його власник (як /tmp ). «Темний каталог» : chmod a-r+x darkcat — у каталог можна зайти ( cd ) і прочитати файл, якщо знаєш його ім'я, але ls видасть Permission denied . Це показує, що r для каталогу — це право бачити список , а x — право входити . Приклад: спільна папка для команди Група і користувачі: groupadd developers , useradd -G developers dev , useradd -G developers test . Каталог: mkdir /home/shared && chgrp developers /home/shared . Права групі на запис + SGID: chmod 2775 /home/shared (2 = SGID, далі rwxrwxr-x ). За потреби sticky bit, щоб не видаляли чужі файли: chmod +t /home/shared ."}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Вхід по SSH-ключах", "url": "lectures/week-1/lecture-2.html#ssh", "text": "Вхід по SSH-ключах SSH (Secure Shell) — протокол захищеного віддаленого доступу, типово TCP-порт 22 . Використовує асиметричне шифрування : приватний ключ лишається у вас, публічний кладемо на сервер у ~/.ssh/authorized_keys . Пара ключів. Приватний ключ нікому не передаємо; на сервер потрапляє лише публічний. ssh-keygen -t rsa -b 4096 # створити пару ключів ssh-copy-id user@192.168.0.10 # додати публічний ключ на сервер # те саме вручну: cat ~/.ssh/id_rsa.pub | ssh user@192.168.0.10 \"cat >> ~/.ssh/authorized_keys\" ssh -i ~/.ssh/id_rsa user@192.168.0.10 # вхід з указаним ключем На сервері шлях до ключів задає AuthorizedKeysFile .ssh/authorized_keys у /etc/ssh/sshd_config . Віртуалізація Для практики Linux зазвичай ставлять у віртуальну машину (наприклад, VirtualBox): гіпервізор відокремлює залізо від гостьових ОС і дозволяє запускати кілька систем одночасно. Детально — у лекції 9."}, {"title": "Лекція 2 · Linux: основи ОС, команди, користувачі та права доступу", "section": "Типові помилки", "url": "lectures/week-1/lecture-2.html#mistakes", "text": "Типові помилки chmod 777 «щоб точно запрацювало». Це дає запис усім користувачам — діра в безпеці. Видавайте мінімум: файли 644, каталоги і скрипти 755, а власника задавайте через chown . У відносній формі a означає «інші». u — власник, g — група, o — інші, a — усі (all) одразу. usermod -G group user додає групу. Без -a він замінює список груп. Правильно: usermod -aG group user . Скрипт script.sh не запускається «бо нема .exe». Потрібен атрибут x ( chmod +x ) і шлях: ./script.sh — поточний каталог не входить у PATH . Sticky bit ставиться як chmod g+t . Sticky bit — це біт для «інших»: chmod +t dir (або o+t , числом — 1777 ). У ls -l видно t в останній позиції."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Вступ", "url": "lectures/week-1/lecture-3.html", "text": ""}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-3.html#goals", "text": "Чого ви навчитесь Створити і запустити bash-скрипт (shebang, права, позиційні параметри). Правильно працювати зі змінними: присвоєння без пробілів, різниця \"подвійних\" і 'одинарних' лапок. Використовувати спецзмінні $0 $1 $# $@ $? $$ та підстановку команд. Писати умови if [ … ] з правильними операторами для чисел і рядків. Писати цикли for , while , until і функції з local -змінними."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Оболонки і чому bash", "url": "lectures/week-1/lecture-3.html#shells", "text": "Оболонки і чому bash Shell (оболонка) — програма, що приймає ваші команди і запускає їх. У Linux є багато оболонок: sh (Bourne), csh , ksh , tcsh , zsh , але найпопулярніша — bash (Bourne Again Shell) . Вона сумісна з sh , взяла найкраще з ksh і csh та відповідає стандарту POSIX . Bash чи Python? Питання з чату лекції. Bash «склеює» POSIX-утиліти ( grep , cp , systemctl …) і є майже в будь-якій системі, а Python може бути не встановлений (у мінімальних образах на кшталт Alpine навіть bash буває відсутній — там sh ). Для коротких сценаріїв розгортання — bash, для складної логіки й обробки даних — Python."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Перший скрипт", "url": "lectures/week-1/lecture-3.html#first", "text": "Перший скрипт Перший рядок — shebang #!/bin/bash : він каже ОС, яким інтерпретатором виконувати файл. #!/bin/bash # hello.sh — коментар починається з # name=\"DevOps\" echo \"Hello, $name! Сьогодні: $(date +%F)\" chmod +x hello.sh # дати право на виконання ./hello.sh # запуск із поточного каталогу bash hello.sh # або явно через інтерпретатор"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Змінні та лапки", "url": "lectures/week-1/lecture-3.html#vars", "text": "Змінні та лапки Змінні не оголошуються — створюються при присвоєнні. Значення завжди зберігаються як рядки ; арифметика перетворює їх на числа. Присвоєння — без пробілів навколо = : count=0 . Звернення — через $ : $count або ${count} . Тип не фіксований: count=0 , потім count=Sunday — легально, але погана практика. Одна змінна — один тип даних. \\ — символ екранування: зберігає буквальне значення наступного символу ( \\$ виведе знак долара). \"Подвійні лапки\" Змінні підставляються . var=\"test string\" echo \"Value: $var\" # Value: test string 'Одинарні лапки' Усе буквально , без підстановки. var=\"test string\" echo 'Value: $var' # Value: $var Рядки з пробілами чи спецсимволами обов'язково беріть у лапки. Ввести значення з клавіатури — команда read : read -p \"Введіть ім'я: \" user echo \"Привіт, $user\" Змінні середовища Є локальні змінні (лише в поточній оболонці) і змінні середовища (environment) , які задає система і успадковують дочірні процеси. Перелік — команда env ; створити свою — export NAME=value . Змінна Що містить PATH Список каталогів через : , де шукаються команди HOME , PWD Домашній і поточний каталог USER , LOGNAME Поточний користувач HOSTNAME , SHELL Ім'я машини, шлях до оболонки PS1 Вигляд запрошення: \\u користувач, \\w каталог, \\W його остання частина, \\t час, \\d дата, \\$ символ запрошення Ініціалізаційні файли: /etc/profile , /etc/profile.d/ , ~/.bash_profile (login-оболонка), ~/.bashrc і /etc/bashrc (інтерактивна), ~/.bash_logout (вихід)."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Спеціальні змінні і підстановка команд", "url": "lectures/week-1/lecture-3.html#special", "text": "Спеціальні змінні і підстановка команд Змінна Значення $0 Ім'я скрипта $1 … $9 , ${10} Позиційні параметри (аргументи) $# Кількість аргументів \"$*\" Усі аргументи одним рядком \"$@\" Усі аргументи окремими рядками (безпечно для циклів) $? Код завершення останньої команди: 0 — успіх , інше — помилка $$ PID поточного процесу #!/bin/bash # ./args.sh one two → 2 / ./args.sh / one echo $# echo $0 echo $1 Підстановка команд вставляє вивід команди у змінну. Старий синтаксис — зворотні лапки `cmd` (не плутати з одинарною лапкою!), сучасний і зручніший — $(cmd) : list=`ls -l` # як на слайдах files=$(ls | wc -l) # рекомендований синтаксис, можна вкладати echo \"Файлів: $files\""}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Арифметика", "url": "lectures/week-1/lecture-3.html#math", "text": "Арифметика Вирази обчислюються через $(( вираз )) (старий варіант — $[ вираз ] ) або команду let . Bash працює лише з цілими числами — дробових немає. echo $(( 100 / 3 )) # 33 — ціла частина! myvar=\"56\" echo $(( myvar + 12 )) # 68 myvar=$(( myvar + 1 )) # інкремент let COUNTER=COUNTER+1 # те саме через let"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Умови: if і вирази test", "url": "lectures/week-1/lecture-3.html#if", "text": "Умови: if і вирази test if / elif / else / fi. Гілки elif і else необов'язкові. if [ \"$myvar\" -eq 3 ]; then echo \"myvar = 3 як число\" elif [ \"$myvar\" = \"3\" ]; then echo \"myvar = 3 як рядок\" else echo \"інше\" fi if [ -z \"$1\" ]; then echo \"Порожній параметр\"; exit 1; fi Синтаксис [ — це команда, тому пробіли обов'язкові : після [ , перед ] і навколо операторів. [ $a -eq 1 ] ✓, [$a -eq 1] ✗. Якщо then / do на тому ж рядку — перед ним ставте ; . Порівняння Числа Рядки дорівнює / не дорівнює -eq / -ne = або == / != більше / більше або рівно -gt / -ge > (за алфавітом) менше / менше або рівно -lt / -le < (за алфавітом) довжина > 0 / = 0 — -n str / -z str Також є файлові оператори : -d (це каталог), -f (звичайний файл), -e (існує), та логічні : ! , && , || ."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Цикли", "url": "lectures/week-1/lecture-3.html#loops", "text": "Цикли Цикл Виконується Приклад for … in для кожного елемента списку файли, аргументи, сервери while поки умова істинна лічильник, читання рядків until поки умова хибна (до моменту, коли стане істинною) чекати, поки сервіс підніметься for x in one two three; do echo \"number $x\" done for f in /etc/r*; do # перебір файлів за маскою if [ -d \"$f\" ]; then echo \"$f (dir)\"; else echo \"$f\"; fi done COUNTER=0 while [ $COUNTER -lt 10 ]; do # 0..9 echo \"The counter is $COUNTER\" COUNTER=$(( COUNTER + 1 )) done n=0 until [ $n -eq 10 ]; do # теж 0..9 echo $n; n=$(( n + 1 )) done Серед елементів мови також є select (меню вибору), функції та перехоплення сигналів trap (наприклад, прибрати тимчасові файли при Ctrl+C)."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Функції та область видимості", "url": "lectures/week-1/lecture-3.html#functions", "text": "Функції та область видимості За замовчуванням змінні в bash глобальні : функція, що змінює myvar , змінить її для всього скрипта. Щоб змінна жила лише у функції — оголосіть її local . Без local myvar=\"hello\" myfunc() { myvar=\"one two three\" for x in $myvar; do echo $x; done } myfunc echo \"$myvar / $x\" # one two three / three З local myvar=\"hello\" myfunc() { local x local myvar=\"one two three\" for x in $myvar; do echo $x; done } myfunc echo \"$myvar / $x\" # hello / (x порожня) Що повертає функція? Питання з чату: return N повертає лише код завершення 0–255 (читається через $? ), як у будь-якої команди. Щоб повернути дані, функція виводить їх через echo , а викликач забирає через $(…) : get_ip() { hostname -I | awk '{print $1}'; } is_root() { [ \"$(id -u)\" -eq 0 ]; } # код 0 = «істина» ip=$(get_ip) if is_root; then echo \"root on $ip\"; else echo \"not root\"; fi"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Практика: мінімальний deployment-скрипт", "url": "lectures/week-1/lecture-3.html#deploy", "text": "Практика: мінімальний deployment-скрипт Результат курсу — уміти написати bash-скрипт розгортання. Ось шаблон, що поєднує все з лекції: аргументи, перевірки, функції, коди завершення. #!/bin/bash # deploy.sh <git-url> [branch] — розгорнути сайт у /var/www/html/app set -e # зупинитись на першій помилці REPO=\"$1\"; BRANCH=\"${2:-main}\"; TARGET=/var/www/html/app log() { echo \"[$(date +%T)] $*\"; } if [ $# -lt 1 ]; then echo \"Usage: $0 <git-url> [branch]\"; exit 1 fi if [ \"$(id -u)\" -ne 0 ]; then echo \"Run as root (sudo)\"; exit 1 fi if [ -d \"$TARGET/.git\" ]; then log \"Оновлюю код ($BRANCH)\" git -C \"$TARGET\" pull origin \"$BRANCH\" else log \"Клоную $REPO\" git clone -b \"$BRANCH\" \"$REPO\" \"$TARGET\" fi chown -R apache:apache \"$TARGET\" systemctl restart httpd log \"Готово, код завершення: $?\""}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Типові помилки", "url": "lectures/week-1/lecture-3.html#mistakes", "text": "Типові помилки name = \"Ivan\" — з пробілами. Bash сприйме name як команду. Правильно: name=\"Ivan\" . [ \"$a\" = 10 ] для порівняння чисел / -eq для рядків. Числа: -eq -ne -lt -le -gt -ge . Рядки: = != -z -n . «010» і «10» рівні як числа, але не як рядки. Змінна без лапок: [ -z $1 ] , rm $file . Якщо значення порожнє або з пробілами — синтаксична помилка чи видалення не того. Пишіть \"$1\" , \"$file\" . echo $(( 7 / 2 )) дасть 3.5. Bash рахує лише цілі: результат 3 . Для дробів — bc або awk . return \"текст\" поверне рядок із функції. return — тільки код 0–255. Дані — через echo і $(func) ."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Вступ", "url": "lectures/week-1/lecture-4.html", "text": ""}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-4.html#goals", "text": "Чого ви навчитесь Описати шлях запиту від введення адреси в браузері до відображення сторінки. Пояснити властивості HTTP (request-response, stateless) і роль cookies. Розрізняти HTTP-методи, GET vs POST у формах, URL vs URI. Порівняти 2-tier, 3-tier і N-tier архітектури, frontend і backend, монолітну та мікросервісну. Спроєктувати REST-ендпоінти для CRUD і викликати їх через curl ."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Клієнт-сервер і веб", "url": "lectures/week-1/lecture-4.html#client-server", "text": "Клієнт-сервер і веб Модель клієнт-сервер розділяє систему на клієнтів і сервери, що спілкуються мережею. Клієнт ініціює сеанс і надсилає запити; сервер чекає запитів від будь-яких клієнтів і відповідає. Мобільні застосунки — теж клієнти: вони звертаються до вебсерверів і вебсервісів. Вебсайт переважно показує інформацію (контент однаковий для всіх), вебзастосунок — інтерактивний: користувач створює і змінює дані (той самий CRUD з лекції 1). Hypertext Гіпертекст Нелінійний текст із посиланнями на інші тексти (термін Теда Нельсона, ~1965). Hypermedia Гіпермедіа Гіпертекст, що містить не лише текст, а й графіку, відео, звук. HTTP HyperText Transfer Protocol Протокол обміну гіпертекстом за схемою «запит — відповідь»."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Як працює HTTP-запит", "url": "lectures/week-1/lecture-4.html#http-flow", "text": "Як працює HTTP-запит Шлях запиту. Спочатку ім'я перетворюється на IP (DNS), потім іде HTTP-запит, сервер загортає дані в HTTP-відповідь. Властивості HTTP Request-response: транзакцію завжди починає клієнт, сервер генерує відповідь. Ідентифікація ресурсу: кожен запит містить URI. Stateless (без стану): сервер не пам'ятає попередніх запитів — кожен запит незалежний. Метадані: заголовки (headers) передають інформацію про дані — тип вмісту, довжину, кукі, авторизацію. GET /index.html HTTP/1.1 ← рядок запиту: метод, шлях, версія Host: shop.com ← заголовки Accept: text/html HTTP/1.1 200 OK ← рядок статусу Content-Type: text/html; charset=utf-8 Set-Cookie: session=abc123 <html>…</html> ← тіло відповіді Класи кодів статусу: 2xx — успіх (200 OK, 201 Created), 3xx — перенаправлення (301, 302), 4xx — помилка клієнта (400, 401, 403, 404), 5xx — помилка сервера (500, 502, 503). URL, URI, URN URI — рядок, що ідентифікує ресурс. URL — підвид URI, що вказує, де ресурс і як до нього дістатися (схема + адреса). URN — ідентифікує ресурс за ім'ям . Кожен URL — це URI, але не кожен URI — URL."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "HTTP-методи", "url": "lectures/week-1/lecture-4.html#methods", "text": "HTTP-методи Методи («дієслова») показують, що зробити з ресурсом: GET , POST , PUT , PATCH , DELETE , HEAD , OPTIONS , TRACE , CONNECT . Метод може бути безпечним (не змінює дані), ідемпотентним (повтор дає той самий результат) і кешованим . Метод Дія (CRUD) Безпечний Ідемпотентний GET Read — отримати так так POST Create — створити ні ні PUT Update — замінити повністю ні так PATCH Update — змінити частину полів ні не гарантовано DELETE Delete — видалити ні так HEAD як GET, але без тіла відповіді так так GET vs POST у HTML-формах Звичайна HTML-форма вміє лише GET і POST . Дані форми завжди передаються як словник ключ=значення (ключ — атрибут name поля), пари з'єднуються через & : view=home&op=translate&sl=en&tl=uk&text=advertisement . GET Дані в URI (рядок запиту після ? ). Обмеження довжини URI (~2048 символів у багатьох браузерах). Видно в адресному рядку, історії, логах → не для паролів. Можна зберегти в закладки. POST Дані в тілі (body) запиту. Розмір тіла протоколом не обмежений. Не видно в URL (але без HTTPS не зашифровано!). Для створення ресурсів, логіну, завантаження файлів. Інструктор у чаті наголосив: на практиці найчастіше трапляються GET і POST, але правильний REST-стиль використовує всі базові методи — цього очікують у командах."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Cookies: стан поверх stateless-протоколу", "url": "lectures/week-1/lecture-4.html#cookies", "text": "Cookies: стан поверх stateless-протоколу"}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "2-tier, 3-tier, N-tier", "url": "lectures/week-1/lecture-4.html#tiers", "text": "2-tier, 3-tier, N-tier 2-tier: клієнт (браузер) ↔ вебсервер (який сам працює і з даними). 3-tier: клієнт ↔ сервер застосунку ↔ окремий сервер БД. N-tier: додаткові рівні — балансувальники навантаження, кілька серверів застосунку, кеші. Масштабується горизонтально. Класичний вебзастосунок (3-tier): БД зберігає дані, вебсервер містить бізнес-логіку і шар доступу до даних і динамічно генерує HTML . Явного поділу на frontend/backend немає — усе на сервері."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Frontend, backend і AJAX", "url": "lectures/week-1/lecture-4.html#front-back", "text": "Frontend, backend і AJAX Backend (server-side) Код виконується на сервері під керуванням вебсервера. Мови: Perl, PHP, Python, Java, C#, Ruby, JavaScript (Node.js). БД: Oracle, MS SQL, MySQL, PostgreSQL, DB2, Firebird… Frontend (client-side) Код виконується на машині клієнта в браузері: HTML, CSS, JavaScript і фреймворки. AJAX (Asynchronous JavaScript and XML) — підхід, що дозволив розділити логіку між frontend і backend. Розроблений Microsoft у 1999, назву дав Джессі Джеймс Гаррет у 2005. JavaScript у браузері надсилає запит асинхронно і оновлює частину сторінки без її перезавантаження . Сьогодні замість XMLHttpRequest використовують fetch або бібліотеки на кшталт axios, а для двостороннього каналу в реальному часі — WebSocket. За словами інструктора, AJAX не застарів — змінилися бібліотеки, а призначення в цих технологій різне. Формати даних JSON { \"id\": 3, \"title\": \"DevOps\", \"tags\": [\"ci\", \"cd\"] } XML <book id=\"3\"> <title>DevOps</title> </book>"}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "API і REST", "url": "lectures/week-1/lecture-4.html#rest", "text": "API і REST API (Application Programming Interface) — набір функцій і процедур, через які одна програма отримує доступ до даних і можливостей іншої програми, сервісу чи ОС. REST (Representational State Transfer) — архітектурний стиль вебсервісів. Кожна одиниця інформації однозначно визначається URL (URL фактично стає «первинним ключем»), а дії задаються HTTP-методами ; операції — без стану . Запит Що робить GET /book/3 отримати книгу №3 GET /book/3/page/35 сторінка 35 книги 3 (вкладені ресурси) POST /book додати книгу (дані в тілі) PUT /book/3 замінити книгу 3 (дані в тілі) PATCH /book/3 змінити окремі поля DELETE /book/3 видалити книгу 3 Виклик API через curl # GET — список ресурсів curl https://api.example.com/clubs # POST з JSON-тілом curl -X POST https://api.example.com/signin \\ -H \"Content-Type: application/json\" \\ -d '{\"email\": \"test@gmail.com\", \"password\": \"user\"}' # запит з токеном авторизації, -i показує заголовки відповіді curl -i -H \"Authorization: Bearer <token>\" -X GET https://api.example.com/user/32 Ключі curl: -X — метод, -H — заголовок, -d — тіло, -i — показати заголовки відповіді. Зручно поєднувати з jq для читабельного JSON."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Моноліт vs мікросервіси", "url": "lectures/week-1/lecture-4.html#micro", "text": "Моноліт vs мікросервіси Монолітна архітектура Один застосунок: інтерфейс, логіка і доступ до даних в одній програмі на одній платформі. Просто розробити і розгорнути на старті. Важко масштабувати частинами; одна помилка може покласти все. Мікросервіси Набір малих незалежних сервісів (користувачі, замовлення, оплата), кожен зі своєю БД, спілкуються через API. Масштабуються і розгортаються окремо. Складніше: мережа, моніторинг, оркестрація → тут і потрібні Docker та CI/CD."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Типові помилки", "url": "lectures/week-1/lecture-4.html#mistakes", "text": "Типові помилки POST безпечний, бо дані «сховані». POST лише не показує дані в URL. Без HTTPS тіло запиту передається відкритим текстом, як і кукі. Сервер сам пам'ятає, що я залогінений. HTTP stateless. «Пам'ять» забезпечують cookies/токени, які клієнт надсилає з кожним запитом. URL і URI — різні непов'язані речі. URL — підмножина URI: ідентифікатор, що ще й вказує розташування ресурсу. Видаляти через GET /deleteBook?id=3 — нормально. Технічно можливо, але порушує семантику: GET має бути безпечним (його кешують, префетчать). Для видалення — DELETE /book/3 ."}, {"title": "Лекція 5 · LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "section": "Вступ", "url": "lectures/week-1/lecture-5.html", "text": ""}, {"title": "Лекція 5 · LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-5.html#goals", "text": "Чого ви навчитесь Пояснити, з чого складається LAMP і чим від нього відрізняється LEMP. Орієнтуватися в конфігурації Apache: httpd.conf , DocumentRoot , <Directory> , <VirtualHost> , модулі. Розуміти, навіщо mod_rewrite , .htaccess і директива AllowOverride . Знайти й прочитати логи Apache ( ErrorLog , CustomLog ). Відтворити послідовність розгортання PHP-застосунку на CentOS і зробити бекап БД."}, {"title": "Лекція 5 · LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "section": "Що таке LAMP", "url": "lectures/week-1/lecture-5.html#stack", "text": "Що таке LAMP LAMP реалізує 3-рівневу архітектуру з лекції 4: клієнт (браузер) → сервер застосунку (вебсервер) → сервер БД . LAMP = Linux + Apache + MySQL + PHP (історично P — також Perl або Python). Apache HTTP Server Вебсервер Виріс із NCSA HTTPd (Роб МакКул). Назву пояснюють як «a patchy server» — сервер із латками. За статистикою зі слайдів (2018) — 43% активних сайтів. MySQL СКБД Створена MySQL AB (1995), у 2008 куплена Sun, у 2010 разом із Sun — Oracle. Сумісний форк — MariaDB. PHP Скриптова мова Расмус Лердорф, 1994. Ключові версії: PHP 5 (2004), PHP 7 (2015), PHP 8 (2020). Популярний фреймворк — Laravel. Чому LAMP досі вивчають? У чаті лекції було гаряче обговорення «застарілості». Позиція інструктора: стек простий, дає швидкий результат і показує принципи, які потім переносяться на NGINX, Node.js чи Java/Tomcat. Близько третини сайтів працює на WordPress, тобто на LAMP. На практиці часто комбінують Apache + NGINX (NGINX спереду як проксі)."}, {"title": "Лекція 5 · LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "section": "Конфігурація Apache", "url": "lectures/week-1/lecture-5.html#config", "text": "Конфігурація Apache Apache налаштовується директивами в текстових файлах. Головний файл — httpd.conf (у CentOS: /etc/httpd/conf/httpd.conf ; у Debian/Ubuntu: /etc/apache2/apache2.conf + каталоги sites-enabled , mods-enabled ). Типи файлів (MIME) читаються з mime.types (директива TypesConfig ). Віртуальні хости і модулі рекомендують виносити в окремі файли. Директива Призначення DocumentRoot Каталог, з якого віддаються файли. Шлях з URL додається до нього: /var/www/html + /shop/index.php <Directory> Група директив для каталогу, його підкаталогів і файлів <VirtualHost> Налаштування окремого сайту — кілька доменів на одному сервері LoadModule Підключити модуль (кожен модуль має свої директиви) AllowOverride Які директиви дозволено перевизначати в .htaccess ErrorLog , CustomLog , LogFormat Журнал помилок, журнал доступу та його формат <VirtualHost *:80> ServerName shop.example.com DocumentRoot /var/www/html/opencart/upload <Directory /var/www/html/opencart/upload> AllowOverride All # дозволити .htaccess (потрібно для mod_rewrite) Require all granted </Directory> ErrorLog /var/log/httpd/shop-error.log CustomLog /var/log/httpd/shop-access.log combined </VirtualHost> Модулі Apache має модульну архітектуру : ядро — mod_core , решта підключаються через LoadModule . Часто використовувані: ssl , rewrite , proxy , userdir , headers , php . mod_rewrite — переписує URL «на льоту» за правилами на основі регулярних виразів (PCRE). Може мапити URL на файл, робити редирект або внутрішній проксі-запит. Директиви: RewriteEngine , RewriteRule , RewriteCond , RewriteBase , RewriteMap , RewriteOptions . Саме він робить «гарні» URL типу /product/42 замість index.php?route=product&id=42 . mod_proxy — перетворює Apache на проксі/шлюз, підтримує протоколи і алгоритми балансування навантаження. RewriteEngine On RewriteCond %{REQUEST_FILENAME} !-f # якщо такого файла немає… RewriteRule ^product/([0-9]+)$ index.php?id=$1 [L] # …передати в PHP .htaccess і AllowOverride .htaccess («розподілений конфіг») — файл із директивами в каталозі сайту, що діє на цей каталог і всі вкладені. Потрібен, коли власник сайту не має root-доступу до сервера. Директива AllowOverride визначає, що з нього застосову"}, {"title": "Лекція 5 · LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "section": "Практика: розгортання OpenCart на CentOS", "url": "lectures/week-1/lecture-5.html#deploy", "text": "Практика: розгортання OpenCart на CentOS На лекції розгортали інтернет-магазин OpenCart 2.x. Послідовність — типова для будь-якого PHP-застосунку. Підготовка ОС (лише для навчального стенда!). Вимкнути firewalld і SELinux, підключити репозиторій EPEL, за проблем із DNS прописати nameserver 8.8.8.8 у /etc/resolv.conf . MySQL. Додати репозиторій MySQL, встановити mysql-community-server , увімкнути автозапуск і запустити, знайти тимчасовий пароль у /var/log/mysqld.log , запустити mysql_secure_installation . Користувач і БД. Створити користувача, видати права, створити БД з кодуванням UTF-8. Apache + PHP. Встановити httpd і пакети PHP ( php-mysql , php-gd , php-mbstring …), увімкнути автозапуск; для mod_rewrite змінити AllowOverride None → All . Код застосунку. Завантажити архів ( wget ), розпакувати ( unzip ), скопіювати в /var/www/html , створити config.php з config-dist.php , віддати файли користувачу apache . Веб-інсталятор. Відкрити http://IP/opencart/upload/install/ , ввести параметри БД; після встановлення видалити каталог install/ . # сервіси керуються через systemctl systemctl enable --now mysqld # автозапуск + старт (enable і start в одній команді) systemctl status mysqld grep password /var/log/mysqld.log # тимчасовий пароль root mysql_secure_installation yum -y install httpd php php-mysql php-gd php-mbstring php-xml systemctl enable --now httpd cp -r opencart /var/www/html/ chmod -R 775 /var/www/html/opencart chown -R apache:apache /var/www/html/opencart systemctl restart httpd CREATE USER 'shop'@'localhost' IDENTIFIED BY 'StrongPass!1'; -- локальний доступ CREATE USER 'shop'@'%' IDENTIFIED BY 'StrongPass!1'; -- з будь-якого хоста GRANT ALL ON opencart.* TO 'shop'@'localhost'; CREATE DATABASE opencart CHARACTER SET utf8 COLLATE utf8_bin; SHOW DATABASES; 'user'@'localhost' і 'user'@'%' — різні облікові записи MySQL: перший підключається лише з цього ж сервера, другий — з будь-якої адреси. На слайдах права видаються як GRANT ALL ON *.* (на всі БД) — для стенда ок, для production давайте права лише на потрібну БД. Нюанси зі слайдів Старий OpenCart 2.x не працював з новим механізмом автентифікації MySQL 8 і з режимом sql_mode = 'MYSQL40' , тому на лекції кори"}, {"title": "Лекція 5 · LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "section": "Резервні копії БД", "url": "lectures/week-1/lecture-5.html#backup", "text": "Резервні копії БД mysqldump --all-databases > dump.sql # усі БД mysqldump -u root -p opencart > opencart.sql # одна БД mysql -u root -p opencart < opencart.sql # відновлення Зверніть увагу на напрямок перенаправлення з лекції 2: > — вивантажити дамп у файл, < — подати файл на вхід клієнту mysql ."}, {"title": "Лекція 5 · LAMP-стек: Apache, MySQL, PHP і розгортання вебзастосунку", "section": "Типові помилки", "url": "lectures/week-1/lecture-5.html#mistakes", "text": "Типові помилки Правила .htaccess «не працюють», хоча файл на місці. Перевірте AllowOverride для каталогу (при None файл ігнорується) і чи завантажено mod_rewrite . Після змін у конфігу — systemctl restart httpd . Сайт видає 403/500 — одразу chmod -R 777 . Спершу error_log . Зазвичай досить віддати файли користувачу вебсервера ( chown -R apache:apache ) з правами 755/644. Вимкнути firewall і SELinux на production, як на лабі. На production відкривають лише потрібні порти (80/443) і налаштовують SELinux-контексти, а не вимикають захист. Забути видалити install/ після встановлення CMS. Каталог інсталятора дозволяє перевстановити сайт і перезаписати БД — його видаляють одразу."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "Вступ", "url": "lectures/week-2/lecture-6.html", "text": ""}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-6.html#goals", "text": "Чого ви навчитесь Назвати рівні OSI і TCP/IP , протоколи на кожному рівні та одиниці даних (кадр, пакет, сегмент). Розрізняти три види адрес: MAC (пристрій), IP (вузол у мережі), порт (процес). Порахувати за IP і маскою адресу мережі, broadcast і кількість хостів. Знати приватні діапазони, спеціальні адреси і правила скорочення IPv6. Пояснити NAT (SNAT, DNAT, PAT) і VPN, а також діагностувати мережу через ping і traceroute ."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "Протоколи і моделі", "url": "lectures/week-2/lecture-6.html#basics", "text": "Протоколи і моделі Сучасне ПЗ здебільшого розподілене — його частини спілкуються мережею за моделлю клієнт-сервер. Клієнт ініціює запити, чекає і отримує відповіді, може працювати з кількома серверами; сервер ніколи не ініціює обмін першим, а чекає запитів. Визначення Протокол — набір правил обміну даними: типи повідомлень, їхній синтаксис і значення полів, порядок надсилання і отримання, дії сторін і взаємодія з нижчим рівнем. Застосунки дають інтерфейс до мережевих сервісів, сервіси (демони) надають функціональність (вебсервер, DNS-сервер), а протоколи забезпечують їхню взаємодію. OSI vs TCP/IP. Верхні три рівні OSI в TCP/IP об'єднані в один Application, нижні два — у Network Access. (*ARP працює на межі L2/L3.) OSI — еталонна (описова) модель: як пояснив інструктор, жодна реальна мережа не відповідає їй на 100%. Часто її ділять на «програмні» рівні 7–5 і «мережеві» 4–1. Реальний інтернет працює на стеку TCP/IP . Інкапсуляція Під час відправлення кожен рівень додає до даних свій заголовок : застосунок → TCP-сегмент (порти) → IP-пакет (IP-адреси) → Ethernet-кадр (MAC-адреси) → біти в кабелі. Отримувач «розпаковує» в зворотному порядку — декапсуляція ."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "Три рівні адресації", "url": "lectures/week-2/lecture-6.html#addressing", "text": "Три рівні адресації MAC · L2 · 48 біт Фізична адреса пристрою Унікальна адреса мережевої карти, напр. 1A:2B:3C:4D:5E:6F . Перші 3 байти — виробник (OUI). Діє в межах локального сегмента. IP · L3 Логічна адреса вузла Ідентифікує вузол у мережі та дозволяє маршрутизацію між мережами. «Ім'я — що шукаємо, адреса — де воно, маршрут — як дістатися». Port · L4 · 0–65535 Адреса процесу Дозволяє багатьом програмам (Zoom, браузер, Viber) ділити один мережевий інтерфейс. IPv4 IPv6 Розгорнуто 1981 1998 Розмір 32 біти 128 біт Запис десятковий з крапками: 192.149.252.76 шістнадцятковий: 3FFE:F200:0234:AB00:0123:4567:8901:ABCD Префікс 192.149.0.0/24 3FFE:F200:0234::/48 Кількість адрес 2³² ≈ 4,3 млрд 2¹²⁸ ≈ 3,4·10³⁸ Порти Запит іде з динамічного порту клієнта на well-known порт сервера (наприклад, клієнт :51234 → сервер :443). Діапазони 0–1023 — well-known (системні) 1024–49151 — registered 49152–65535 — dynamic / private Порти, які треба пам'ятати 20/21 — FTP (дані / команди) · 22 — SSH · 23 — Telnet 25 — SMTP · 110 — POP3 · 53 — DNS 80 — HTTP · 443 — HTTPS · 3306 — MySQL DNS (Domain Name System) перетворює доменні імена ( google.com ) на IP-адреси. Перевірити: nslookup google.com або dig google.com ."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "IPv4: мережа, хост, маска", "url": "lectures/week-2/lecture-6.html#ipv4", "text": "IPv4: мережа, хост, маска 32 біти IPv4 записують 4 октетами. Старші біти — мережева частина (P біт), молодші — частина хоста (N біт), P + N = 32 . Довжину мережевої частини задає префікс /P або маска : 32-бітне число, де мережеві біти = 1, хостові = 0. Адреса мережі Усі біти хоста = 0. Ідентифікує підмережу, використовується в маршрутизації: 192.168.25.0 . Broadcast Усі біти хоста = 1. Пакет усім у підмережі: 192.168.25.255 . Адреси хостів Усе між ними: 192.168.25.1–254 . Кількість = 2 N − 2 . Побітове І (AND). IP & маска = адреса мережі. Два хости в одній мережі, якщо результат однаковий. Приклад: ділимо /24 на підмережі Subnetting — позичаємо S біт з хостової частини в мережеву: підмереж стає 2 S , хостів у кожній — 2 N − 2 . Переваги: простіше керування, адресація і маршрутизація, локалізація трафіку. Критерії поділу — географія, призначення, відповідальність. Завдання: мережу 192.168.25.0/24 поділити на 4 підмережі. 4 = 2², отже позичаємо S = 2 біти: новий префікс /26 , маска 255.255.255.192 (11000000 = 128+64 = 192). Хостових біт лишилось N = 32 − 26 = 6 → у кожній підмережі 2⁶ = 64 адреси, з них 62 хости. Крок між мережами — 64: .0 , .64 , .128 , .192 . Для першої: мережа 192.168.25.0 , хости .1–.62 , broadcast .63 . Хост 192.168.25.100 потрапляє в другу підмережу .64/26 (broadcast .127 ). Префікс Маска Хостів /8 255.0.0.0 16 777 214 /16 255.255.0.0 65 534 /24 255.255.255.0 254 /26 255.255.255.192 62 /30 255.255.255.252 2 (з'єднання «точка-точка») Класи, приватні та спеціальні адреси Клас Перший октет Приватний діапазон A (старший біт 0) 0–127 10.0.0.0/8 B (10…) 128–191 172.16.0.0/12 C (110…) 192–223 192.168.0.0/16 D (1110…) 224–239 multicast E (1111…) 240–255 зарезервовано Спеціальні адреси: 0.0.0.0 — маршрут за замовчуванням («будь-яка адреса»), 127.0.0.0/8 — loopback ( 127.0.0.1 — «я сам»), 169.254.0.0/16 — link-local (немає DHCP), 192.0.2.0/24 — TEST-NET для документації, 255.255.255.255 — обмежений broadcast. Види передачі: unicast — одному пристрою; broadcast — усім у підмережі (limited — у своїй, directed — у віддаленій); multicast — вибраній групі."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "IPv6 коротко", "url": "lectures/week-2/lecture-6.html#ipv6", "text": "IPv6 коротко 128 біт = 8 груп по 4 hex-цифри (хекстети). Масок немає — лише префікс: /64 означає 64 біти мережі. Скорочення: Прибрати ведучі нулі в кожній групі: 2001:0DB0:0000:123A:0000:0000:0000:0030 → 2001:DB0:0:123A:0:0:0:30 . Одну (найдовшу) послідовність нульових груп замінити на :: — лише один раз : 2001:DB0:0:123A::30 . Loopback в IPv6 — ::1 ."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "Діагностика: ping і traceroute", "url": "lectures/week-2/lecture-6.html#tools", "text": "Діагностика: ping і traceroute Перевірка Що показує ping 127.0.0.1 Чи працює локальний стек TCP/IP. Нічого не каже про кабель і налаштування IP/маски/шлюзу ping <шлюз> Локальна мережа: IP, маска, комутатор, шлюз ping 8.8.8.8 Вихід в інтернет. Може «не пінгуватись», якщо ICMP заблоковано traceroute host ( tracert у Windows) Маршрут пакетів і затримка (RTT) на кожному вузлі ping використовує ICMP Echo Request/Echo Reply; traceroute — ICMP Time Exceeded від кожного маршрутизатора. Типовий маршрут: локальний роутер (ваш шлюз) → PoP провайдера → регіональний Tier 2 ISP → IXP (точка обміну трафіком) → магістральний Tier 1 ISP → мережа отримувача."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "NAT і PAT", "url": "lectures/week-2/lecture-6.html#nat", "text": "NAT і PAT NAT (Network Address Translation) переписує IP-адреси (і порти) в пакетах, що проходять через маршрутизатор. Так багато «сірих» (приватних) адрес виходять в інтернет через одну «білу» (публічну). PAT на прикладі зі слайдів. Роутер запам'ятовує, якому внутрішньому хосту належить публічний порт 8801, і повертає йому відповідь. Тип Суть SNAT (Source NAT) Доступ з локальної мережі в інтернет; запит ініціює внутрішній хост, підміняється адреса відправника DNAT (Destination NAT) Доступ з інтернету до внутрішнього хоста; підміняється адреса отримувача PAT (Port Address Translation) Багато клієнтів за однією публічною IP, розрізняються портами (1024–65535). Також «port forwarding» Static / Dynamic NAT Одна приватна ↔ одна публічна / багато приватних ↔ пул публічних Masquerading Різновид SNAT: зовнішня адреса береться автоматично з інтерфейсу (для динамічних «білих» IP) Переваги NAT Економія публічних IPv4-адрес Обмеження доступу ззовні (безпека) Приховування внутрішньої архітектури Недоліки NAT Не всі протоколи з ним працюють Навантаження на проміжний пристрій Складніше ідентифікувати користувачів (багато з'єднань з однієї IP) Важкий доступ до внутрішніх ресурсів ззовні DMZ (демілітаризована зона) — окремий сегмент для публічних серверів (веб, пошта), ізольований від внутрішньої мережі."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "VPN", "url": "lectures/week-2/lecture-6.html#vpn", "text": "VPN VPN (Virtual Private Network) — мережа поверх іншої, зазвичай публічної й недовіреної, мережі. Трафік тунелюється і шифрується . Intranet VPN — об'єднати кілька офісів однієї організації в одну захищену мережу. Remote Access VPN — захищений доступ окремого (мобільного) користувача до корпоративної мережі. Client/Server VPN — захист даних між двома вузлами всередині корпоративної мережі. Переваги: тунелювання, шифрування, автентифікація/авторизація/облік (AAA), приховування внутрішньої архітектури, віддалений доступ. Недолік — додатковий трафік (накладні витрати на заголовки та шифрування)."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IP-адресація, порти, NAT і VPN", "section": "Типові помилки", "url": "lectures/week-2/lecture-6.html#mistakes", "text": "Типові помилки У мережі /24 можна адресувати 256 хостів. 256 адрес, але хостів 2⁸ − 2 = 254: адреса мережі та broadcast не призначаються пристроям. Успішний ping 127.0.0.1 = мережа працює. Loopback перевіряє лише локальний стек TCP/IP, а не кабель, IP, маску чи шлюз. Хост «не пінгується», отже він вимкнений. ICMP часто блокують фаєрволи. Перевірте сервіс напряму: curl , telnet host port , nc -zv host 443 . 2001:DB8::1::5 — коректне скорочення. :: можна використати лише один раз, інакше неможливо визначити, скільки нулів у кожному пропуску."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Вступ", "url": "lectures/week-2/lecture-7.html", "text": ""}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-7.html#goals", "text": "Чого ви навчитесь Пояснити, яку бізнес-проблему розв'язують хмари (CapEx → OpEx, еластичність). Назвати 5 базових характеристик , моделі сервісів і 4 моделі розгортання за NIST. Зважити переваги і недоліки хмар (vendor lock-in, «усе ламається»). Розрізняти регіони і зони доступності , зональні та регіональні ресурси. Зіставити ключові сервіси AWS, Azure і GCP."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Звідки взялися хмари", "url": "lectures/week-2/lecture-7.html#history", "text": "Звідки взялися хмари Період Як розміщували сервіси Проблема 1990-ті Своє залізо і ПЗ, канал від провайдера, власне приміщення, свій штат IT/Ops Платиш за все, навіть коли не використовуєш 2000-ні Оренда стійок у спільному дата-центрі (colocation) Сервери, ПЗ і чергові адміни «з пейджером 24/7» — досі свої Хмари Оренда ресурсів через інтернет із погодинною/посекундною оплатою Нові ризики: залежність від провайдера Ідея Google — будувати надійність на дешевому стандартному залізі (commodity hardware) і програмно обходити відмови. Amazon на початку 2000-х мав надлишок потужностей під пікові розпродажі й вирішив здавати їх в оренду — так з'явився AWS. Вправа на масштабування Припустимо, 1 сервер обслуговує 20 тис. користувачів. Скільки серверів купувати, якщо аудиторія росте так: Чому прогнозувати важко. Купили під прогноз — у січні–березні сервери простоюють, у травні «успіх-катастрофа»: попит утричі більший, а нове залізо їде тижнями. Чому власне залізо масштабувати складно: великі капітальні витрати наперед ; на масштабі залізо часто ламається ; потрібні спеціалісти; замовлення нового обладнання займає тижні ; глобальне розгортання вимагає глобальної команди. Хмара дозволяє додати 7 серверів за хвилини і прибрати їх, коли пік мине."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Модель хмари за NIST", "url": "lectures/week-2/lecture-7.html#nist", "text": "Модель хмари за NIST Визначення NIST Хмарні обчислення — модель повсюдного, зручного мережевого доступу на вимогу до спільного пулу конфігурованих обчислювальних ресурсів (мережі, ВМ, сховища, застосунки, сервіси), які можна швидко виділити і звільнити з мінімальними зусиллями з управління чи взаємодії з провайдером. Структура моделі NIST: 5 характеристик + 3 (і більше) моделі сервісів + 4 моделі розгортання. Характеристика Що означає на практиці On-demand self-service Створюєте ВМ самі в консолі/API, без дзвінка провайдеру Broad network access Доступ через мережу зі стандартних пристроїв Resource pooling Ресурси провайдера спільні для багатьох клієнтів (multi-tenancy) Rapid elasticity Швидко масштабуєте вгору і вниз під навантаження Measured service Використання вимірюється — платите за фактом (pay-as-you-go) Моделі розгортання: public — ресурси провайдера для всіх (AWS, GCP, Azure); private — хмара для однієї організації; hybrid — поєднання власної інфраструктури і публічної хмари; community — спільна хмара для групи організацій зі спільними вимогами. Розподіл відповідальності (повторення лекції 1): в IaaS провайдер керує мережею, сховищем, серверами і віртуалізацією; у PaaS — ще й ОС, middleware і runtime; у SaaS — усім, клієнт лише користується."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Переваги і недоліки", "url": "lectures/week-2/lecture-7.html#pros-cons", "text": "Переваги і недоліки Переваги «Assetless»: не треба купувати залізо і приміщення. Плата за використання , масштабування вгору/вниз із посекундною тарифікацією. Менший штат IT/Ops : автоматизація замість лінійного росту персоналу. Вибір рівня: від DevOps (керує клієнт) до NoOps (керує провайдер). Готові сервіси: ML API (зір, мова, мовлення), GIS, сховища даних. Недоліки Vendor lock-in: важко переїхати GCP ↔ AWS ↔ Azure. Закритий код сервісів — важче дебажити . Commodity hardware: треба проєктувати систему з розрахунку на часті відмови. «Everything fails all the time» — Вернер Фогельс, CTO Amazon. Ризик неочікуваних рахунків (з чату: при реєстрації часто треба прив'язати картку). Моделі управління , які пропонує провайдер: клієнт робить усе (хмара як віртуальний дата-центр), клієнт робить частину (DevOps, гібрид), клієнт не робить нічого (NoOps, повністю керовані сервіси). Розробники, за слайдом, віддають перевагу останньому."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Регіони і зони", "url": "lectures/week-2/lecture-7.html#geo", "text": "Регіони і зони Ієрархія інфраструктури. Регіон → кілька ізольованих зон → кілька дата-центрів у зоні. AWS: Availability Zone (AZ) — ізольоване розташування з кількох з'єднаних дата-центрів; регіон — географічна група з 2+ AZ (напр. us-east-1 ). GCP: регіон — незалежна географічна область із зон; зона — окремий «домен відмови» в регіоні. Зональні ресурси недоступні, якщо впала зона; регіональні — розгорнуті з резервуванням у кількох зонах регіону; мультирегіональні/глобальні — розподілені між регіонами (з компромісом щодо затримки чи узгодженості даних). Висновок для проєктування: критичний сервіс розміщують щонайменше у двох зонах . Кількість регіонів і зон швидко змінюється — актуальні цифри дивіться на сайтах провайдерів."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "AWS, GCP, Azure: що є що", "url": "lectures/week-2/lecture-7.html#providers", "text": "AWS, GCP, Azure: що є що У кожного провайдера понад 100 продуктів. GCP зі слайдів: першим запровадив посекундну оплату, робить ставку на open source (Kubernetes, TensorFlow, Go) проти vendor lock-in, власна глобальна оптоволоконна мережа. Абстракції в усіх провайдерів однакові — різняться назви. Категорія AWS Azure GCP Віртуальні машини (IaaS) EC2 Virtual Machines Compute Engine PaaS для застосунків Elastic Beanstalk App Service / Cloud Services App Engine Serverless-функції (FaaS) Lambda Functions Cloud Functions Kubernetes EKS AKS GKE Об'єктне сховище S3 Blob Storage Cloud Storage Блокові диски EBS Disk Storage Persistent Disk Реляційна БД RDS, Aurora SQL Database Cloud SQL, Spanner NoSQL DynamoDB Cosmos DB Bigtable, Datastore Мережа VPC Virtual Network (VNet) VPC DNS / балансування Route 53 / ELB Traffic Manager / Load Balancer Cloud DNS / Cloud Load Balancing Архівне сховище Glacier Archive Storage Nearline / Coldline Сильні сторони за PDF-порівнянням: AWS — лідер ринку, найширший і найзріліший набір сервісів, глобальне покриття; Azure — інтеграція з продуктами Microsoft, гібридна хмара, підтримка великих організацій; GCP — орієнтація на cloud-native, open source і портативність, гнучкі контракти та знижки за тривале використання. Усі мають free tier для старту."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Типові помилки", "url": "lectures/week-2/lecture-7.html#mistakes", "text": "Типові помилки Хмара — це просто «чужий сервер». Хмару визначають 5 характеристик NIST: самообслуговування, мережевий доступ, пул ресурсів, еластичність і вимірюваність. Орендований VPS без них — звичайний хостинг. У хмарі нічого не ламається — за це відповідає провайдер. Залізо в хмарі звичайне і відмовляє регулярно. Надійність — відповідальність архітектури: кілька зон, резервні копії, моніторинг. Регіон і зона — одне й те саме. Регіон — географічна область, що містить кілька ізольованих зон. Резервування між зонами захищає від аварії одного дата-центру. Хмара завжди дешевша. Хмара вигідна при змінному навантаженні. За постійного високого навантаження і без контролю витрат рахунок може перевищити власне залізо."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Вступ", "url": "lectures/week-2/lecture-8.html", "text": ""}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-8.html#goals", "text": "Чого ви навчитесь Дати визначення IaC і пояснити, чим він кращий за ручне налаштування. Розрізняти configuration management , server templating і provisioning та назвати інструменти кожного типу. Пояснити ключові поняття Terraform: provider, resource, variable, output, state . Прочитати і написати простий HCL-блок. Знати, що робить кожна команда циклу init → plan → apply → destroy ."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Що таке Infrastructure as Code", "url": "lectures/week-2/lecture-8.html#iac", "text": "Що таке Infrastructure as Code Визначення Infrastructure as Code (IaC) — процес управління IT-інфраструктурою, що застосовує найкращі практики DevOps-розробки до хмарних ресурсів. Ресурси організації кодифікуються в текстові файли , які зберігаються в системі контролю версій (Git) — це відкриває feature-гілки, pull request-и і, як наслідок, CI/CD для інфраструктури. Нагадування з «хмарної піраміди»: що нижче (IaaS), то більше контролю і роботи з інфраструктурою — саме тут працює DevOps і саме тут IaC дає найбільший ефект. Вручну («ClickOps») Кроки в консолі ніде не записані Друге середовище відрізняється від першого Відновлення після аварії — з пам'яті Немає рев'ю змін Як код Файли = документація інфраструктури dev/stage/prod з одного коду — однакові Відтворення за хвилини Зміни проходять pull request і історію Git Передісторія: спершу інфраструктуру автоматизували скриптами (Bash, Python, Ruby, PowerShell). Потім з'явилися спеціалізовані інструменти: Vagrant, Docker, Terraform, Ansible, Packer. Повна «карта» — CNCF Landscape: Ansible, Chef, Puppet, SaltStack, Pulumi, Terraform та десятки інших."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Три типи IaC-інструментів", "url": "lectures/week-2/lecture-8.html#types", "text": "Три типи IaC-інструментів Типи IaC. На практиці їх комбінують: Terraform створює ВМ, Ansible налаштовує її, або ВМ запускається з готового образу Packer/Docker. Idempotent Ідемпотентність Повторний запуск дає той самий результат: якщо nginx уже встановлено, вдруге нічого не зміниться. Immutable infrastructure Незмінна інфраструктура Сервер не «латають» на місці, а замінюють новим із нового образу. Менше дрейфу конфігурації. Declarative Декларативний підхід Описуєте бажаний стан («2 ВМ типу e2-small»), а інструмент сам вирішує, що створити, змінити чи видалити. Так працює Terraform."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Чому Terraform", "url": "lectures/week-2/lecture-8.html#terraform", "text": "Чому Terraform Безкоштовний і з відкритим кодом (HashiCorp), написаний на Go. Простий в установці — один бінарний файл; перевірка: terraform -version . Мультиплатформний: сотні провайдерів — AWS, GCP, Azure, VirtualBox, Docker, Kubernetes… «Керуй будь-чим, що має API». Цілі: уніфікований погляд на ресурси, підтримка IaaS/PaaS/SaaS, безпечні й передбачувані зміни, робочий процес, що не залежить від технології."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Ключові поняття Terraform", "url": "lectures/week-2/lecture-8.html#concepts", "text": "Ключові поняття Terraform Provider Провайдер Плагін, що взаємодіє з API сервісу (hashicorp/aws, hashicorp/google, terra-farm/virtualbox). Завантажується з Terraform Registry. Resource Ресурс Блок, що описує один чи кілька об'єктів інфраструктури: ВМ, мережу, DNS-запис, навіть локальний файл. Variable Змінна Пара ключ-значення для налаштування конфігурації без зміни коду. Output Вихідне значення Значення, яке модуль повертає (виводить у CLI або передає іншим конфігураціям), напр. IP створеної ВМ. State Стан Закешована інформація про керовану інфраструктуру: зв'язок «ресурс у коді ↔ реальний об'єкт». Змінні Вид Як задається Input Блок variable ; значення передаються до виконання (CLI -var , файл .tfvars , default) Local Блок locals — внутрішні обчислені значення, можуть посилатися на інші змінні Output Блок output — вивести результат у CLI Environment Змінні оточення з префіксом TF_VAR_ : export TF_VAR_db_username=admin Типи значень: string , number (цілі й дробові), bool , list / tuple ( [\"us-west-1a\", \"us-west-1c\"] , індекс з 0), map / object ( {name = \"Mabel\", age = 52} ), null ."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "HCL: мова конфігурації", "url": "lectures/week-2/lecture-8.html#hcl", "text": "HCL: мова конфігурації HCL (HashiCorp Configuration Language) візуально схожа на JSON, але має власні структури. Основна мета — оголошувати ресурси ; решта можливостей лише робить це гнучкішим. Три складові: блоки (контейнери з типом і мітками), аргументи (ім'я = значення) і вирази (значення або посилання на інші значення). # загальний синтаксис <BLOCK TYPE> \"<BLOCK LABEL>\" \"<BLOCK LABEL>\" { <IDENTIFIER> = <EXPRESSION> # argument } Приклад: ВМ у Google Cloud (зі слайдів) terraform { required_providers { google = { source = \"hashicorp/google\" , version = \"3.5.0\" } } } provider \"google\" { credentials = file( \"my_gcp.json\" ) # ключ сервісного акаунта — НЕ комітити в Git! project = \"project_vasis\" region = \"europe-north1\" zone = \"europe-north1-a\" } resource \"google_compute_instance\" \"vm_instance\" { name = \"moodle\" machine_type = \"e2-small\" boot_disk { initialize_params { image = \"ubuntu-2004-focal-v20210720\" } } } Змінні та виходи (практика з VirtualBox) variable \"type_network\" { default = \"bridged\" } resource \"virtualbox_vm\" \"node\" { count = 2 # дві однакові ВМ name = format( \"node-%02d\" , count.index + 1) # node-01, node-02 image = \"…/ubuntu/boxes/xenial64/…/virtualbox.box\" cpus = 2 memory = \"2048 mib\" network_adapter { type = var.type_network } } output \"IPAddr\" { value = element(virtualbox_vm.node.*.network_adapter.0.ipv4_address, 1) } На лекції провайдер terra-farm/virtualbox (alpha-версія) збирали з вихідного коду ( go build ) і запускали terraform apply -parallelism=1 , щоб ВМ створювались по черзі. Це дозволяє вчитися IaC локально, без хмарних рахунків."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Життєвий цикл: init → plan → apply → destroy", "url": "lectures/week-2/lecture-8.html#lifecycle", "text": "Життєвий цикл: init → plan → apply → destroy Команда Що робить terraform init Ініціалізує робочий каталог: завантажує провайдерів. Першою після написання нової конфігурації або клонування з Git terraform plan Будує план: читає поточний стан реальних об'єктів, порівнює конфігурацію з попереднім state, пропонує дії, щоб реальність відповідала коду terraform apply Виконує план (з підтвердженням yes ) і оновлює state terraform destroy Видаляє всі ресурси, якими керує конфігурація State Terraform зберігає стан, щоб зіставляти ресурси з коду з реальними об'єктами , відстежувати метадані і пришвидшувати роботу з великою інфраструктурою. За замовчуванням — локальний файл terraform.tfstate ; у команді його зберігають віддалено (наприклад, у S3 чи GCS), щоб усі працювали з одним станом. Безпека State і файли облікових даних (як my_gcp.json ) можуть містити секрети. Додавайте їх у .gitignore ; паролі передавайте через TF_VAR_… або менеджер секретів."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Типові помилки", "url": "lectures/week-2/lecture-8.html#mistakes", "text": "Типові помилки Одразу terraform apply без plan . Plan показує, що буде створено (+), змінено (~) і знищено (−) . Читайте його завжди — деякі зміни перестворюють ресурс. Змінити ВМ вручну в консолі, «бо швидше». З'являється дрейф: код і реальність розходяться, наступний apply поверне або зламає зміни. Усі зміни — через код. Видалити terraform.tfstate , «бо заважає». Без state Terraform «забуде» створені ресурси і спробує створити їх заново. State бережуть і зберігають віддалено. Terraform і Ansible — взаємозамінні. Terraform — provisioning (створити інфраструктуру), Ansible — configuration management (налаштувати ПЗ на ній). Їх часто використовують разом."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Вступ", "url": "lectures/week-2/lecture-9.html", "text": ""}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-9.html#goals", "text": "Чого ви навчитесь Порівняти віртуальні машини і контейнери за архітектурою та витратою ресурсів. Назвати механізми ядра Linux, на яких тримаються контейнери: namespaces , cgroups , capabilities . Розрізняти образ , контейнер , registry і пояснити архітектуру Docker Engine. Написати Dockerfile і пояснити різницю між RUN , CMD , ENTRYPOINT , EXPOSE . Користуватися основними командами: pull , build , run -p , ps , exec , stop , rm , rmi ."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Віртуалізація", "url": "lectures/week-2/lecture-9.html#virtualization", "text": "Віртуалізація Принцип «один застосунок — один фізичний сервер» означає: багато серверів, ліцензії ОС для кожного і низьке завантаження кожної машини. Розділяй і володарюй — розв'язок дає віртуалізація. Визначення Гіпервізор (VMM, virtual machine monitor) — ПЗ, прошивка або залізо, що створює і запускає віртуальні машини. Комп'ютер із гіпервізором — host (хост), кожна ВМ — guest (гість). Приклади: KVM, Xen, VMware, Oracle VirtualBox. Але для клієнта цінність — застосунок , а не ОС. У кожній ВМ своя повна ОС, яка споживає багато CPU, RAM і диска: OS ≠ business value ."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "ВМ vs контейнер", "url": "lectures/week-2/lecture-9.html#vm-vs-container", "text": "ВМ vs контейнер Головна різниця: ВМ віртуалізує залізо (у кожної своє ядро), контейнер — ОС (ядро спільне). Контейнери легші, але слабше ізольовані. Віртуальна машина Контейнер Що віртуалізує Залізо (через гіпервізор) ОС (OS-level virtualization) Ядро Власне в кожній ВМ Спільне ядро хоста Ресурси Багато CPU/RAM/диска на ОС Менше CPU, RAM і диска Ізоляція Сильніша Достатня для більшості задач, але слабша Інша ОС Можна (Windows-гість на Linux-хості) Тільки під ядро хоста (Linux-контейнери на Linux) Конфлікт бібліотек: два застосунки на одному сервері потребують різних версій однієї бібліотеки — у спільній ОС конфлікт. У контейнерах кожен застосунок несе свій user space зі своїми версіями."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Як працюють контейнери: механізми ядра", "url": "lectures/week-2/lecture-9.html#kernel", "text": "Як працюють контейнери: механізми ядра Контейнери — це можливість Unix-подібних ОС , а не винахід Docker. Docker лише зручна обгортка над функціями ядра. Namespaces Ізоляція «що бачить процес» PID — свої процеси (усередині свій PID 1), MNT — своя файлова система, NET — своя мережа, USER — свої користувачі й привілеї. Control groups (cgroups) Обмеження ресурсів Групують процеси і ставлять ліміти: скільки CPU, RAM, I/O може взяти контейнер. Capabilities Дрібні привілеї Замість «усе або нічого» root — окремі дозволи (напр. лише прив'язка до порту < 1024). Формула зі слайдів cgroups + namespaces + image = Docker-контейнер . Namespaces дають ізоляцію, cgroups — ліміти, образ — файлову систему із застосунком."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Docker: архітектура і терміни", "url": "lectures/week-2/lecture-9.html#docker", "text": "Docker: архітектура і терміни Docker — набір PaaS-продуктів, що використовують віртуалізацію рівня ОС для постачання ПЗ в пакетах — контейнерах . Docker Engine — клієнт-серверний застосунок: CLI-клієнт спілкується з демоном dockerd через REST API . Image Образ Шаблон застосунку: набір файлів і параметрів. Конструкція часу збирання (build time). Не файлова система і не віртуальний диск — по суті tar-архів шарів з ієрархією. Container Контейнер Запущений екземпляр образу — ізольований процес на Docker-хості зі спільним ядром. Конструкція часу виконання (runtime). Registry Реєстр Мережеве сховище образів, приватне чи публічне. Найбільший публічний — Docker Hub. Dockerfile Рецепт образу Текстовий файл з інструкціями, які Docker виконує, щоб зібрати образ. Шари образу Образ складається з шарів : кожна інструкція Dockerfile — окремий шар, усі шари образу лише для читання . Коли запускається контейнер, зверху додається тонкий записуваний шар — зміни контейнера живуть лише в ньому і зникають разом із контейнером. Спільні шари (напр. базовий python ) зберігаються один раз для всіх образів."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Dockerfile", "url": "lectures/week-2/lecture-9.html#dockerfile", "text": "Dockerfile Dockerfile схожий на shell-скрипт із ключовими словами: розширює базовий образ ( FROM ) і дає новий образ . Формат: # коментар і ІНСТРУКЦІЯ аргументи . docker build збирає образ з Dockerfile і контексту — набору файлів за шляхом (PATH) або URL Git-репозиторію. Інструкція Призначення FROM Базовий образ (перша інструкція) RUN Крок збирання : виконати команду і зафіксувати результат у новому шарі (встановити пакети). Може бути багато COPY / ADD Скопіювати файли з контексту в образ ( ADD вміє ще URL і розпакування архівів) WORKDIR Робочий каталог для наступних інструкцій ENV , LABEL Змінні оточення, метадані EXPOSE Документує , який порт слухає контейнер (саме по собі порт не публікує) CMD Команда за замовчуванням при старті контейнера. Діє лише остання; перевизначається: docker run image інша_команда ENTRYPOINT Головна команда контейнера; CMD тоді стає її аргументами за замовчуванням VOLUME , HEALTHCHECK , USER … Томи для даних, перевірка здоров'я, користувач тощо"}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Практичний кейс: Python-вебсервер у контейнері", "url": "lectures/week-2/lecture-9.html#case", "text": "Практичний кейс: Python-вебсервер у контейнері Файли з архіву лекції server.zip : server.py #!/usr/bin/env python3 import http.server import socketserver handler = http.server.SimpleHTTPRequestHandler with socketserver.TCPServer((\"\", 1234), handler) as httpd: httpd.serve_forever() Dockerfile FROM python:latest ADD server.py /server/ ADD index.html /server/ WORKDIR /server/ CMD [\"python\", \"./server.py\"] EXPOSE 1234 docker build -t serverimage . # -t — тег (ім'я) образу, . — контекст docker run --name myserver -d -p 1234:1234 serverimage # -d у фоні, -p ХОСТ:КОНТЕЙНЕР curl http://localhost:1234 # Hello world! Мапінг портів: перше число — порт хоста, друге — порт усередині контейнера."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Шпаргалка команд", "url": "lectures/week-2/lecture-9.html#commands", "text": "Шпаргалка команд Команда Що робить docker pull openjdk:8-jdk Завантажити образ з Docker Hub (тег після : , без тегу — latest ) docker images Список локальних образів docker ps / docker ps -a Запущені / усі контейнери docker run --name java8 -it openjdk:8-jdk Створити й запустити контейнер з інтерактивним терміналом ( -i вхід, -t TTY) docker stop <id> / docker start <id> Зупинити / запустити існуючий контейнер docker exec -it java8 bash Виконати команду (shell) у запущеному контейнері docker cp app.jar java8:/app.jar Скопіювати файл у контейнер docker commit <id> imagejava8 Зберегти стан контейнера як новий образ (краще — Dockerfile) docker logs <id> Логи контейнера docker rm <id> / docker rmi <id> Видалити контейнер / образ Встановлення на Linux на лекції: curl -fsSL https://get.docker.com/ | sh , далі systemctl enable --now docker . З чату: Docker працює й на Windows; образ той самий, важлива лише архітектура процесора. Альтернативи Docker (наприклад, Podman) використовують ті самі механізми ядра."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Типові помилки", "url": "lectures/week-2/lecture-9.html#mistakes", "text": "Типові помилки Образ і контейнер — одне й те саме. Образ — незмінний шаблон (build time), контейнер — його запущений екземпляр (runtime). З одного образу можна запустити багато контейнерів. EXPOSE 1234 робить сервіс доступним ззовні. EXPOSE лише документує порт. Публікує його docker run -p ХОСТ:КОНТЕЙНЕР . Запускати сервер через RUN python server.py . RUN виконується під час збирання образу. Команда старту контейнера — CMD або ENTRYPOINT (тому на слайді RUN закоментовано). Зберігати дані БД усередині контейнера. Записуваний шар зникає з контейнером. Дані виносять у томи ( -v / VOLUME ). Контейнер = «легка ВМ» з власним ядром. Контейнери ділять ядро хоста; ізоляцію дають namespaces, а ліміти — cgroups."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Вступ", "url": "lectures/week-2/lecture-10.html", "text": ""}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-10.html#goals", "text": "Чого ви навчитесь Пояснити, яку проблему розв'язує VCS, і порівняти моделі lock-modify-unlock та copy-modify-merge . Розрізняти централізовані (SVN) і розподілені (Git) системи. Описати три зони Git — робочий каталог, індекс, репозиторій — і рух змін між ними. Користуватися базовими командами, розв'язувати конфлікти, відкочувати зміни ( reset vs revert ). Пояснити Git Flow , GitHub Flow і процес pull request ."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Навіщо контроль версій", "url": "lectures/week-2/lecture-10.html#why", "text": "Навіщо контроль версій Звичайний файловий сервер дає спільне сховище, але не пам'ятає історії. Репозиторій — особливий файловий сервер, що пам'ятає кожну зміну : кожного файла і навіть структури каталогів. Клієнт зазвичай бачить останню версію, але може переглянути будь-який попередній стан. Інструменти в історичному порядку: CVS (1986, клієнт-сервер, розвиток зупинено 2008), Apache Subversion (SVN) (2000, наступник CVS; клієнти TortoiseSVN, RabbitVCS), Microsoft VSS (для малих проєктів, підтримку завершено 2016), TFS (Team Foundation Server у складі Visual Studio Team System), і нарешті Git (2005). За словами інструктора, SVN зараз переважно трапляється в історії старих проєктів — основний інструмент Git. Проблема одночасного редагування Гаррі і Саллі одночасно редагують один файл. Гаррі зберігає першим, Саллі — за хвилину, і непомітно перезаписує зміни Гаррі. Вони не втрачені назавжди (система пам'ятає історію), але в останній версії їх немає. Lock-Modify-Unlock Щоб редагувати, файл треба заблокувати ; інші лише читають. Конфліктів немає, але люди чекають . Гаррі забув зняти блокування і пішов у відпустку — Саллі потрібен адміністратор. Copy-Modify-Merge Кожен працює зі своєю робочою копією , паралельно. Наприкінці копії зливаються (merge) ; VCS допомагає, але відповідає людина. Якщо зміни перетинаються — конфлікт , який розв'язує людина. На практиці конфлікти рідкісні й дешевші за очікування блокувань. Жодна система не виявить семантичні конфлікти (код зливається, але логіка ламається) — тому потрібні комунікація, рев'ю і тести. Централізовані vs розподілені VCS"}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Git: старт", "url": "lectures/week-2/lecture-10.html#git", "text": "Git: старт Git — розподілена система контролю версій з акцентом на швидкість, цілісність даних і нелінійну розробку (багато гілок). Створена Лінусом Торвальдсом у 2005 для розробки ядра Linux. sudo apt install git # Debian/Ubuntu (Windows: git-scm.com/download/win) git config --global user.name \"Ivan Petrenko\" # автор комітів git config --global user.email \"ivan@example.com\" git config --list # перевірити налаштування git help commit # довідка: також git commit --help .gitignore — шаблони файлів, які Git не відстежує: порожні рядки і рядки з # ігноруються, / в кінці — каталог, ! — виняток. *.[oa] # об'єктні файли й архіви /target/ # каталог target у корені doc/*.txt # doc/notes.txt, але не doc/info/arch.txt doc/**/*.txt # усі .txt у doc на будь-якій глибині .env # секрети — ніколи не в Git"}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Три зони Git і рух змін", "url": "lectures/week-2/lecture-10.html#areas", "text": "Три зони Git і рух змін Транспортні команди Git. Зелені стрілки ведуть зміни «вперед» до сервера, помаранчеві — повертають їх. Базовий цикл git init # новий репозиторій у поточному каталозі git clone https://github.com/user/repo.git # або копія існуючого git remote add origin <url> # прив'язати віддалений репо git remote -v # список remotes git status # що змінено / в індексі git add readme.txt # додати файл в індекс (git add . — усі) git diff --staged # що піде в коміт git commit -m \"Add readme\" # зафіксувати git commit --amend -m \"Better message\" # виправити ОСТАННІЙ коміт (до push!) git push origin main # відправити гілку main git pull origin main # забрати й злити зміни з сервера git log -3 / git log -p -2 / git log --since=2.weeks git reflog # журнал переміщень HEAD — рятує «втрачені» коміти git rm --cached file # прибрати з індексу, залишити на диску git mv old new # перейменувати Конфлікти Якщо дві гілки змінили той самий рядок, Git позначає конфлікт маркерами. Треба вручну залишити потрібний варіант, видалити маркери , зробити git add і коміт. <<<<<<< HEAD:index.html <div id=\"footer\">contact : email.support@github.com</div> ======= <div id=\"footer\">please contact us at support@github.com</div> >>>>>>> iss53:index.html Відкат змін: reset vs revert Команда Робочий каталог Індекс Локальний репо (HEAD) git reset --soft f314b2 без змін без змін переноситься git reset f314b2 (mixed) без змін оновлюється переноситься git reset --hard f314b2 перезаписується оновлюється переноситься reset переписує історію — безпечно лише для локальних, ще не надісланих комітів. Для вже опублікованих змін використовують git revert <sha> : він створює новий коміт , що скасовує старий, і нікому не ламає історію. git push -f (примусово) на спільну гілку — крайній захід."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Гілки і стратегії", "url": "lectures/week-2/lecture-10.html#branches", "text": "Гілки і стратегії git branch testing # створити гілку git checkout testing # перейти (git checkout -b testing — створити й перейти) # … коміти … git checkout main git merge testing # злити testing у поточну (main) git branch -d testing # видалити локально git push origin :testing # видалити на сервері (або --delete testing) Git Flow. Дві «вічні» гілки (main, develop) і тимчасові допоміжні: feature, release, hotfix. Git Flow (Вінсент Дріссен, 2010) main (master) — production-код; develop — передрелізний код. Обидві існують завжди. feature-* : від develop → назад у develop. release-* : від develop → у main і develop (дрібні фікси, метадані релізу). hotfix-* : від main → у main і develop (терміново виправити production). GitHub Flow (GitHub, 2011) Усе в main — завжди готове до деплою. Нова робота — у гілці від main з описовою назвою ( new-oauth2-scopes ). Регулярно комітимо і пушимо гілку на сервер. Потрібен фідбек або готово — відкриваємо pull request . Після рев'ю і схвалення — merge у main і одразу деплой ."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Pull request: командна робота", "url": "lectures/week-2/lecture-10.html#pr", "text": "Pull request: командна робота Pull request (PR) повідомляє команду про зміни, які ви запушили в гілку. У PR обговорюють і переглядають код, додають нові коміти — і лише потім зливають у базову гілку. Це ключовий результат курсу: «репозиторій на GitHub з pull request-ами та рев'ю». Власник репозиторію запрошує учасників (collaborators) і налаштовує правила захисту гілки : зміни в main лише через PR, обов'язкове схвалення. Учасник клонує репозиторій і створює нову гілку. Змінює код → commit → push гілки. Відкриває pull request і чекає рев'ю. Після схвалення зміни зливаються; гілку зазвичай видаляє той, хто зробив merge. Секрети в репозиторії З чату лекції: якщо пароль чи токен випадково потрапив у Git, мало видалити його з історії — секрет треба негайно змінити (відкликати) , бо копії репозиторію вже могли розійтися. Великі бінарні файли в Git не зберігають (для цього є Git LFS)."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Типові помилки", "url": "lectures/week-2/lecture-10.html#mistakes", "text": "Типові помилки git reset --hard або push -f на спільній гілці, щоб «прибрати» коміт. Для опублікованих комітів — git revert : новий коміт, що скасовує зміни, без переписування чужої історії. git pull і git fetch — одне й те саме. fetch лише завантажує зміни в локальний репо; pull = fetch + merge у поточну гілку. Зробив git add — зміни вже на GitHub. add → індекс, commit → локальний репо, і лише push → сервер. Комітити .env , ключі, terraform.tfstate . Додайте їх у .gitignore заздалегідь; секрети зберігайте в Secrets CI-системи."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Вступ", "url": "lectures/week-3/lecture-11.html", "text": ""}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Чого ви навчитесь", "url": "lectures/week-3/lecture-11.html#goals", "text": "Чого ви навчитесь Пояснити, що таке Continuous Integration і з чого складається CI/CD-конвеєр. Описати архітектуру CI-сервера: VCS, тригер, агенти збирання, артефакти, деплой. Встановити Jenkins і знати його ключові налаштування. Прочитати і написати declarative Jenkinsfile : agent , stages , steps , post , parameters , when . Порівняти declarative і scripted pipeline та знати допоміжні інструменти Jenkins."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Continuous Integration", "url": "lectures/week-3/lecture-11.html#ci", "text": "Continuous Integration Визначення Continuous Integration (CI) — практика, коли розробники часто (щонайменше щодня) інтегрують зміни в спільну гілку, а кожна інтеграція перевіряється автоматичним збиранням і тестами . Мета — знаходити помилки інтеграції якнайраніше (класичний опис — стаття Мартіна Фаулера «Continuous Integration»). CI-цикл. Тригер — webhook на push або періодичне опитування репозиторію (poll SCM). Далі по конвеєру — Continuous Delivery (кожна вдала збірка готова до релізу, вихід у production — після ручного схвалення) і Continuous Deployment (повністю автоматично). Різницю ми розібрали в лекції 1."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Jenkins", "url": "lectures/week-3/lecture-11.html#jenkins", "text": "Jenkins Що це Open-source CI/CD-сервер з вебінтерфейсом. Написаний на Java, працює в servlet-контейнері. Наступник (форк) Hudson. Факти зі слайдів Перший реліз — 2005 (як Hudson), ліцензія MIT, активна незалежна спільнота, 1500+ плагінів . Jenkins 2.0 (2016) Pipeline — «громадянин першого класу»: Pipeline as Code (Jenkinsfile) і новий інтерфейс Blue Ocean. Встановлення (CentOS, як на лекції) java -version # Jenkins потребує Java wget -O /etc/yum.repos.d/jenkins.repo http://jenkins-ci.org/redhat/jenkins.repo rpm --import http://pkg.jenkins-ci.org/redhat/jenkins-ci.org.key yum install jenkins service jenkins start # далі http://server:8080 Налаштування сервісу — /etc/sysconfig/jenkins : JENKINS_HOME=\"/var/lib/jenkins\" (усі задачі, плагіни, історія), JENKINS_USER=\"jenkins\" , JENKINS_PORT=\"8080\" . Після першого входу: оновити/встановити плагіни, налаштувати Maven (для Java-проєктів), Git-плагін, і SSH-ключ для доступу до репозиторію ( ssh-keygen → публічний ключ у GitHub, як у лекції 2). Адреси репозиторіїв Jenkins з часом змінювались — актуальну інструкцію беріть на jenkins.io."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Jenkinsfile: Pipeline as Code", "url": "lectures/week-3/lecture-11.html#jenkinsfile", "text": "Jenkinsfile: Pipeline as Code Jenkinsfile — опис конвеєра на Groovy DSL , що лежить у репозиторії поруч із кодом. Переваги зберігання в SCM: рев'ю й ітерації коду конвеєра, журнал змін (audit trail) , єдине джерело правди . Declarative (з 2017) Декларативна модель, простіший і «суворіший» синтаксис Валідація і візуальний редактор Обмежує можливості — ідеально для типових CD-конвеєрів Scripted Імперативна модель — повноцінна мова програмування Максимальна гнучкість, майже без обмежень Для досвідчених користувачів і складних вимог Спільне: обидва на Groovy, той самий Pipeline-движок, переважно однакові кроки, обидва вміють Shared Libraries і змішуються через крок script . Анатомія declarative pipeline. Stage — логічний етап (видно в UI), step — конкретна дія всередині. Приклад declarative Jenkinsfile Зібрано з фрагментів слайдів (settings, stages, parameters, approval, post): pipeline { agent any triggers { pollSCM( 'H/5 * * * *' ) } // перевіряти репозиторій кожні 5 хв options { timeout(time: 60, unit: 'MINUTES' ) buildDiscarder(logRotator(numToKeepStr: '30' )) // зберігати 30 останніх збірок } parameters { string(name: 'DEPLOY_ENV' , defaultValue: 'TESTING' , description: 'The target environment' ) } environment { AWS_ACCESS_KEY_ID = credentials( 'my-aws-key' ) // секрет із Jenkins Credentials } stages { stage( 'Build & unit tests' ) { steps { checkout scm sh './gradlew build' stash name: 'my-workspace' , includes: 'build/**' } } stage( 'Acceptance tests' ) { parallel { // гілки виконуються одночасно stage( 'Firefox' ) { steps { echo 'testing Firefox' } } stage( 'Chrome' ) { steps { echo 'testing Chrome' } } } } stage( 'Deploy to Stage' ) { when { branch 'master' } // лише для master steps { timeout(time: 30, unit: 'DAYS' ) { input message: 'Deploy to Stage?' , submitter: 'admin,pete.pm' } unstash 'my-workspace' sh \"echo deploying build ${env.BUILD_NUMBER} to ${params.DEPLOY_ENV}\" } } } post { failure { emailext subject: \"FAILED: ${env.JOB_NAME} [${env.BUILD_NUMBER}]\" , body: \"Check console output at ${env.BUILD_URL}\" , recipientProviders: [culprits()] } } } Елемент Що робить agent Де виконувати: any , мітка вузла, Docker-контейнер; agent none на верхньому рівні"}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Масштабування і зручності", "url": "lectures/week-3/lecture-11.html#ecosystem", "text": "Масштабування і зручності Multibranch / Organization Folder — сканує організацію GitHub/Bitbucket, знаходить Jenkinsfile і автоматично створює задачі для кожного репозиторію, гілки й PR. Запуск — через webhook або періодично. Docker-агенти — збірка в контейнері: не треба встановлювати інструменти на сервер, можна кілька версій одного інструмента; також підтримується Kubernetes. Shared Libraries (DRY) — спільний код для всіх задач, завантажується з Git-репозиторію. Інструменти: Blue Ocean (візуалізація і редактор конвеєрів, інтеграція з PR), Snippet Generator ( http://jenkins:8080/pipeline-syntax ), Directive Generator, Replay (перезапустити змінений конвеєр без коміту), автоконвертація Freestyle-задач, лінтер Jenkinsfile з командного рядка, автодоповнення в IntelliJ (GDSL), unit-тести конвеєрів. З чату лекції: комітити в головну гілку вирішує команда (зазвичай через PR), а не DevOps одноосібно; Jenkins і альтернативи (GitHub Actions — наступна лекція) краще вивчати окремо — встановлення і налаштування, потім інтеграції."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Типові помилки", "url": "lectures/week-3/lecture-11.html#mistakes", "text": "Типові помилки Налаштовувати конвеєр кліками в UI (Freestyle) і ніде його не зберігати. Jenkinsfile у репозиторії: рев'ю, історія змін, відтворюваність. Для міграції є автоконвертація Freestyle → Pipeline. Писати пароль прямо в Jenkinsfile. Секрети зберігають у Jenkins Credentials і підставляють через credentials('id') в environment . Плутати stage і step . Stage — етап конвеєра (Build, Test, Deploy), steps — список дій усередині етапу ( sh , echo , git ). Тримати input всередині агента, що займає executor на дні. Для очікування схвалення використовують agent none на верхньому рівні, щоб не блокувати ресурси."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Вступ", "url": "lectures/week-3/lecture-12.html", "text": ""}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Чого ви навчитесь", "url": "lectures/week-3/lecture-12.html#goals", "text": "Чого ви навчитесь Назвати 6 компонентів GitHub Actions і пояснити, як вони пов'язані. Створити workflow-файл у правильному каталозі і прочитати його синтаксис: on , jobs , runs-on , steps , uses , with , run . Використати matrix для тестування на кількох версіях і secrets для токенів. Розібрати workflow «тести → збірка → деплой на Heroku» рядок за рядком. Порівняти GitHub Actions і Jenkins."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Що таке GitHub Actions", "url": "lectures/week-3/lecture-12.html#what", "text": "Що таке GitHub Actions GitHub Actions автоматизує робочі процеси розробки — збирання, тести, деплой, рев'ю, керування гілками й задачами — просто в GitHub . Actions — це повторно використовувані скрипти: можна писати свої (JavaScript, Docker тощо) або брати готові з GitHub Marketplace : надіслати повідомлення в Slack ( slack-send ), завантажити звіт покриття ( codecov ), задеплоїти в Google Cloud ( setup-gcloud ). Готові дії «зшиваються» у workflow ."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Компоненти", "url": "lectures/week-3/lecture-12.html#components", "text": "Компоненти Ієрархія: подія → workflow → jobs (кожен на своєму runner) → steps (дія або команда). Workflow Робочий процес Налаштований автоматизований процес, що запускає один або кілька jobs. YAML-файл у репозиторії. Event Подія Активність у репозиторії, що запускає workflow: push, pull request, розклад, ручний запуск. Job Завдання Набір кроків, що виконуються на одному runner послідовно. Step Крок Або uses (готова дія), або run (shell-команда) — не обидва в одному кроці. Action Дія Застосунок для платформи, що виконує складну повторювану задачу (checkout коду, встановлення Node). Runner Виконавець Сервер, що виконує jobs: GitHub-hosted ( ubuntu-latest , windows-latest , macos-latest ) або self-hosted — на вашому ПК чи в хмарі."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Як увімкнути", "url": "lectures/week-3/lecture-12.html#enable", "text": "Як увімкнути Відкрити репозиторій проєкту на GitHub. Створити каталог .github/workflows/ (саме workflows , у множині) — або вкладка Actions → Set up a workflow чи готовий шаблон. Додати файл у форматі YAML , напр. my-pipeline-ver-1.yml . Щойно файл потрапив у репозиторій, GitHub Actions автоматично починає реагувати на описані події. Результати — на вкладці Actions."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Синтаксис: ключі workflow", "url": "lectures/week-3/lecture-12.html#syntax", "text": "Синтаксис: ключі workflow Ключ Значення name Назва для відображення в інтерфейсі (необов'язкова) on Події-тригери, напр. push у гілку master jobs Перелік jobs; ключ ( build ) — ідентифікатор runs-on Тип runner strategy.matrix Запустити job кілька разів з різними параметрами steps Список кроків job uses Готова дія: власник/репо@версія , локальна папка або Docker-образ with Параметри для дії (наприклад, версія Node) run Shell-команда; | дозволяє кілька рядків env Змінні оточення кроку/job actions/checkout завантажує код репозиторію і гілки, на якій запущено workflow — без нього в runner немає вашого коду . actions/setup-node встановлює Node.js потрібної версії. Вихідний код будь-якої дії можна переглянути на GitHub за назвою (версія — після @ )."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Розбір: тести, збірка і деплой на Heroku", "url": "lectures/week-3/lecture-12.html#example", "text": "Розбір: тести, збірка і деплой на Heroku Workflow зі сторінки курсу (Node.js-застосунок): name: CI on: push: branches: - master # 1. запуск на push у master jobs: build: runs-on: ubuntu-latest # 2. GitHub-hosted runner strategy: matrix: node-version: [14.x, 16.x] # 3. job запуститься двічі steps: - uses: actions/checkout@v1 # 4. забрати код - name: Use Node.js ${{ matrix.node-version }} uses: actions/setup-node@v1 # 5. встановити Node with: node-version: ${{ matrix.node-version }} - name: yarn install run: yarn install # 6. залежності - name: yarn test run: yarn test env: CI: true # 7. тести в CI-режимі - name: yarn build run: yarn run build --if-present # 8. збірка, якщо є скрипт build - name: Add remote origin run: git remote add heroku https://heroku:${{ secrets.HEROKU_API_KEY }}@git.heroku.com/${{ secrets.HEROKU_APP_NAME }}.git - name: Deploy to Heroku run: git push heroku HEAD:master -f # 9. деплой = push у git-репозиторій Heroku Matrix на практиці. Два паралельні запуски. Зверніть увагу: тут деплой виконується в кожній копії matrix — у реальному проєкті деплой виносять в окремий job з needs: build , щоб він ішов один раз. Актуальність прикладу Приклад 2022 року. Відтоді Heroku прибрав безкоштовний тариф (листопад 2022), Node 14/16 більше не підтримуються, а дії мають новіші версії ( actions/checkout@v4 , actions/setup-node@v4 ). Логіку workflow це не змінює."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Secrets, обмеження, self-hosted runners", "url": "lectures/week-3/lecture-12.html#secrets", "text": "Secrets, обмеження, self-hosted runners Опублікований токен — великий ризик. Тому в GitHub є secrets : Settings → Secrets and variables → Actions , створюєте, напр., MY_TOKEN , і в workflow пишете ${{ secrets.MY_TOKEN }} . Значення шифрується і маскується в логах. Також щоразу автоматично доступний ${{ secrets.GITHUB_TOKEN }} для роботи з цим репозиторієм. Self-hosted runner — власна машина (ПК, сервер, хмарна ВМ) реєструється в репозиторії (Settings → Actions → Runners) і виконує jobs: доступ до внутрішньої мережі, своє залізо, без хвилин GitHub. Обмеження: у PDF наведено ліміти на кшталт «до 58 хвилин на workflow» — вони не відповідають поточній документації (зараз, наприклад, job на GitHub-hosted runner може тривати до 6 годин). Ліміти і ціни змінюються — перевіряйте розділ «Usage limits» документації GitHub. Публічні репозиторії мають безкоштовні хвилини. Marketplace : Danger — автоматичне код-рев'ю, Dependabot — оновлення вразливих залежностей, Codecov — звіти покриття. Бейдж статусу в README: ![](https://github.com/<user>/<repo>/actions/workflows/<file>.yml/badge.svg) (у PDF — старіший формат через /workflows/<name>/badge.svg )."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Довідково: деплой статичного сайту на GitHub Pages", "url": "lectures/week-3/lecture-12.html#pages", "text": "Довідково: деплой статичного сайту на GitHub Pages Цей самий навчальний сайт публікується на GitHub Pages. Сучасний мінімальний workflow для статичного сайту (без збирання) виглядає так: name: Deploy site on: push: branches: [main] permissions: contents: read pages: write id-token: write jobs: deploy: runs-on: ubuntu-latest environment: github-pages steps: - uses: actions/checkout@v4 - uses: actions/upload-pages-artifact@v3 with: path: . # що публікувати - uses: actions/deploy-pages@v4 # викласти на Pages"}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "GitHub Actions vs Jenkins", "url": "lectures/week-3/lecture-12.html#vs-jenkins", "text": "GitHub Actions vs Jenkins Jenkins GitHub Actions Де працює Власний сервер (self-hosted) Хмара GitHub (+ опційно self-hosted runners) Опис конвеєра Jenkinsfile , Groovy .github/workflows/*.yml , YAML Розширення 1500+ плагінів Actions з Marketplace Секрети Jenkins Credentials Repository/Organization Secrets Ручне схвалення input Environments з required reviewers Підтримка Ви адмініструєте сервер і плагіни Інфраструктуру підтримує GitHub Коли обирати Складні корпоративні конвеєри, будь-які VCS, повний контроль Код на GitHub, швидкий старт без сервера"}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Типові помилки", "url": "lectures/week-3/lecture-12.html#mistakes", "text": "Типові помилки Файл у .github/workflow/ — і нічого не запускається. Правильний каталог — .github/workflows/ (у множині), формат — YAML ( .yml / .yaml ). Забути actions/checkout і дивуватися, що yarn install не знаходить package.json . Runner стартує порожнім — код треба завантажити першим кроком. uses і run в одному кроці. Кожен крок — або дія ( uses ), або команда ( run ). Розділіть на два кроки. Вставити API-ключ прямо в YAML. Репозиторій (і його історія) може бути публічним. Ключ — у Secrets, у файлі — лише ${{ secrets.NAME }} . Помилки відступів у YAML. YAML чутливий до відступів: лише пробіли, однакова вкладеність для елементів одного рівня."}]};
